				rr = m;
			}
			else {
				ll = m;
			}
//			debug(ll + " " + rr);

			if (rr - ll < 3) {
				for (int m2=ll; m2<=rr; m2++) {
					if (getNumber(x, y, n, m2) >= c) {
						pln(m2);
						return;
					}
				}
			}
		}

	}
