            s=1;
        else{
            s=(4+4*t)/2*t+1;
        }
        if(x+t>n){
            long c=x+t-n;
            s-=c*c;
        }
        if(x-t<=0){
            long c=t-x+1;
            s-=c*c;
        }
        if(y+t>n){
            long c=y+t-n;
            s-=c*c;
        }
        if(y-t<=0){
            long c=t-y+1;
            s-=c*c;
        }
        if(t>x+y-1){
