            sl = "0" + sl;

        low = sl.toCharArray();

        high = sh.toCharArray();

        for (int i = 0; i < low.length; i++) {

            low[i] -= '0';

            high[i] -= '0';

        }

        dp = new long[64][4][4];

        for (int i = 0; i < 64; i++) 

            for(int j = 0;j<4;j++)for(int k=0;k<4;k++)dp[i][j][k]=-1;

        System.out.println(f(0, 0, 0));

    }



    public static void main(String[] args) {

        (new LittleGirlAndMaximumXOR()).run();

    }

