	public static long exp(long a, long n){
		if(n==0){
			return 1;
		}

		if(n % 2 == 0){
			long r = exp(a, n/2);
			return (r*r);
		}else{
			return (a * exp(a,n-1));
		}
	}

	public static long countBinLength(long value) {
	    return Long.SIZE-Long.numberOfLeadingZeros(value);
	}


