class TaskB {
    long n, k;
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextLong();
        k = in.nextLong();
        if (n > k * (k - 1) / 2 + 1)
            out.println(-1);
        else if (n == k * (k - 1) / 2 + 1)
            out.println(k - 1);
        else if (n == 1)
            out.println(0);
        else {
            long left = 0;
            long right = k;
            while (right - left > 1) {
                long middle = (left + right) >> 1;
                if (compare(middle))
                    left = middle;
                else
                    right = middle;
            }
            out.println(left + 1);
        }
    }
    private boolean compare(long m) {
        return (k + k - m - 1) * m / 2 < n - 1;
    }
}

