        long k = in.nextLong();
        if (n == 1) {
            System.out.println(0);
        } else if (k >= n) {
            System.out.println(1);
        } else {
            n -= 1;
            k -= 1;

            if (sum(k) < n) {
                System.out.println(-1);
            } else {

                System.out.println(sumOfPipes(n, k));

            }
        }
    }
