		in.close();
		long val = (k - 1)* k / 2 + 1l;
		if(n > val) {
			System.out.println(-1);
			return;
		}
		if(n == 1l) {
			System.out.println(0);
			return;
		}
		if(k >= n) {
			System.out.println(1);
			return;
		}
		if(n <= 2 * k - 2) {
			System.out.println(2);
			return;
		}
		long st = 2 , end = (int)k - 1;
		while(st <= end) {
			long mid = (end - st) / 2 + st;
			long curr_val = mid * k - ((mid*(mid + 1)) / 2) + 1l;
