            ans %= mod;
            out.println(ans);
        }

        public long dup(long n, long k) {
            long r = n % k;
            n -= r;
            long m = n / k;
            long ans = k * (pow.pow(2, m + 1) - 2);
            ans += r;
            ans = DigitUtils.mod(ans, mod);
            return ans;
        }

