class TaskA {
    public static long MOD = 1000000009L;

    public long pow(long n, long p) {
        if (p == 0)
            return 1L;
        if (p == 1)
            return n;
        long ret = 1L;
        if (p % 2L != 0)
            ret = n;
        long tmp = pow(n, p / 2L);
        ret = (ret * tmp) % MOD;
        ret = (ret * tmp) % MOD;
        return ret;
    }

    public long func(long n, long k) {
        long times = n / k;
        long ret = n - times * k;
        ret += ((pow(2L, times + 1L) + MOD - 2L) % MOD) * k % MOD;
        return ret;
    }

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        long n = in.readLong();
        long m = in.readLong();
        long k = in.readLong();
        long wrong = n - m;
        long wow = n / k;
        long ans;
        if (wrong >= wow)
            ans = m;
        else
            ans = (func(n - wrong * k, k) + (k - 1L) * wrong % MOD) % MOD;

        out.printLine(ans);
    }
}

