		if (k == 0)
			return 1;
		long m1 = pow(n, k / 2);
		m1 = (m1 * m1) % mod;
		if (k % 2 != 0)
			m1 = (m1 * n) % mod;
		return m1;
	}

	long st(int n, int m, int k) {
		int parts = n / k;
		int used = n - m;
		if (parts > n - m) {
			long cur = 0;
			int counter = 0;
			int need = parts - (n - m);
			for (int i = 1; i <= n; i++) {
				if (counter + 1 == k && need <= 0) {
					counter = 0;
					used--;
				} else {
					counter++;
					cur++;
					if (counter == k) {
						counter = 0;
						cur = (cur * 2) % mod;
						need--;
					}
				}
			}
			if (used < 0)
				throw new AssertionError();
			return cur;
		} else {
			return m;
		}
	}

