			long power = ost / k;
			long res = pow(2, power + 1);
			long cur = ((res - 2 + mod) % mod) * k;
			cur %= mod;
			cur += Math.max(0, m - power * k);
			cur %= mod;
			return cur;
		} else {
			return m;
		}
