	private static long binarySearch(long start,long end,long comp) {
		long index=-1;
		while(start<=end) {
		long mid = (start+end)/2;	

			if(countDiff(mid,comp))
			{
				index=mid;
				end=mid-1;
			}
			else {
				start=mid+1;
			}
		}
		return index;

	}

	private static boolean countDiff(long mid,long comp) {
		long sum=0;
		long n=mid;
		while(n>0) {
			sum +=n%10;
			n/=10;
		}
		if(mid-sum>=comp)
			return true;
		else
			return false;
	}


