		}

		return count;

	}

	static long findBs(long n, long s) {

		long low = 10l;

		long high = n;

		long ans = -1;

		while(low<=high) {

			long mid = (low+high)/2;

			long count = count(mid);

			if(mid-count>=s) {

				ans = mid;

				high = mid-1;

			}else

				low = mid+1;

		}

		return ans;

	}

