		//System.out.println(2+" "+(k+1)+" "+m);
		long coeff = power(2L, k+1, m);
		//System.out.println(coeff);
		long r = (coeff%m)*(n%m)%m;
		//System.out.println(r);
		long x = power(2L, k, m)%m-1;
