	static long modExp(long x, long pow) {

		x = x % mod;

	    long res = 1;      

	    while (pow > 0) {

	        if (pow % 2 == 1)
	            res = res * x % mod;

	        pow = pow / 2;
	        x = x * x % mod;  
	    }

	    return res;
	}

	public void run() {

		InputReader s = new InputReader(System.in);
		PrintWriter w = new PrintWriter(System.out);

		int t = 1; 

