			long x = s.nextLong(), k = s.nextLong();

			if(x == 0) {
				w.println(0); continue;
			}

			x = x % mod;

			long res = (modExp(2, k + 1) * x % mod + 1) % mod;
			res = (res + mod - modExp(2, k)) % mod;

