    static class CNastyaAndAWardrobe {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            long mod = (long) (1e9 + 7);
            long n = in.nextLong();
            long k = in.nextLong();
            if (n == 0) {
                out.println(0);
                return;
            }
            long c = (((2 * n - 1) % mod) * pow(2L, k, mod)) % mod + 1;
            c %= mod;
            out.println(c);
        }

        public long pow(long a, long b, long mod) {
            long result = 1;
            while (b > 0) {
                if (b % 2 != 0) {
                    result *= a;
                    result %= mod;
                    b--;
                }
                a *= a;
                a %= mod;
                b /= 2;
            }

            return result % mod;

        }

    }

