	public static long ans(long x, long y, long p)
    {
        long r = 1;     
        x = x % p;
        while (y > 0)
        {
            if((y & 1)==1)
                r = (r * x) % p;
            y = y >> 1; 
            x = (x * x) % p; 
        }
        return r;
    }
