        int mod = 1000000007;

        if(n == 0) {
          out.println(0);
          out.close(); System.exit(0);
        }
        n %= mod;

        long ans = exp(2, (int)((k+1) % (mod-1)), mod);
        ans = (1L*ans * n) % mod;
        ans = ans + mod + 1 - exp(2, (int)((k) % (mod-1)), mod);
        ans %= mod;
        out.println(ans);
