            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public long fastPowerMod(long x, long y, long m) {
            long res = 1;
            x = x % m;
            while (y > 0) {
                if ((y & 1) == 1) {
                    res = (x * res) % m;
                }
                x = (x * x) % m;
                y = y >> 1;
            }
            return res % m;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
