    long mul(long x, long y, long m) {
        long ans = 0;
        while (y>0) {
            if ((y & 1)>0) {
                ans += x;
                if (ans >= m) ans -= m;
            }
            x = x + x;
            if (x >= m) x -= m;
            y >>= 1;
        }
        return ans;
    }

    long modpow(long a, long b,long M)
    {
        long r=1;
        while(b>0)
        {
            if((b&1)>0) r=mul(r,a,M);
            a=mul(a,a,M);
            b>>=1;
        }
        return r;
    }

    long M=(long)1e9+7;
