            writer.println(i);
        }

    }

    static class Utilities {
        public static long mul(long x, long y, long mod) {
            return (x % mod) * (y % mod) % mod;
        }

        public static long power(long a, long k, long m) {
            long res = 1;
            while (k > 0) {
                if ((k & 1) != 0) {
                    res = mul(res, a, m);
                }
                a = mul(a, a, m);
                k >>= 1;
            }
            return res;
        }

    }
