public class C extends PrintWriter {

    final long mod = 1_000_000_007;

    long pow(long n, long p) {
        long r = 1;

        while (p > 0) {
            if (p % 2 == 1) {
                r = (r * n) % mod;
            }
            n = (n * n) % mod;
            p /= 2;
        }

        return r;
    }

    long solve(long n, long k) {

        if (k == 0) {
            return (2 * n) % mod;
        }

        if (n == 0) {
            return 0;
        }

        long m = pow(2, k);

        long a = 2;

        a = (a * n) % mod;
        a = (a * m) % mod;

        long b = (m + mod - 1) % mod;

        return ((a - b + mod) % mod);
    }

    void run() {
        long n = nextLong();
        long k = nextLong();

        println(solve(n, k));
    }

    boolean skip() {
        while (hasNext()) {
            next();
        }
        return true;
    }

    int[][] nextMatrix(int n, int m) {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                matrix[i][j] = nextInt();
        return matrix;
    }

    String next() {
        while (!tokenizer.hasMoreTokens())
            tokenizer = new StringTokenizer(nextLine());
        return tokenizer.nextToken();
    }

    boolean hasNext() {
        while (!tokenizer.hasMoreTokens()) {
            String line = nextLine();
            if (line == null) {
                return false;
            }
            tokenizer = new StringTokenizer(line);
        }
        return true;
    }

    int[] nextArray(int n) {
        int[] array = new int[n];
        for (int i = 0; i < n; i++) {
            array[i] = nextInt();
        }
        return array;
    }

