class trienode{
    trienode[] next=new trienode[26];
    int count;
    char value;
    boolean last;
    trienode() {
        this.value='0';
        this.count=0;
    }
    trienode(char x) {
        this.value=x;
        this.count=1;
    }

}
class trie{
    trienode root=new trienode();
    public void insert(String s) {
        trienode temp=root;
        int length=s.length();
        for(int i=0;i<length;i++) {
            char c=s.charAt(i);
            int index=c-'a';
            if(temp.next[index]==null) {
                temp.next[index]=new trienode(c);
            }
            else {
                temp.next[index].count++;
            }
            if(i==length-1) {
                temp.next[index].last=true;
            }
            temp=temp.next[index];

        }

    }
    public String find(String s) {
        trienode temp=root;
        String ans="";
        int pos=0;
        char c=s.charAt(pos);
        int index=c-'a';
        while(temp.next[index]!=null) {
            temp=temp.next[index];
            ans+=temp.value;
            if(pos==s.length()-1) {
                break;
            }
            c=s.charAt(++pos);
            index=c-'a';

        }
        while(temp.last!=true) {
            int position=-1;
            for(int i=0;i<26;i++) {
            if(temp.next[i]!=null) {
                ans+=temp.next[i].value;
                position=i+0;
                break;
            }

        }
            temp=temp.next[position];
        }
        return ans;
    }
}
