	public static void quickSort(int[] a, int from, int to) {
		if (to - from <= 1) {
			return;
		}
		int i = from;
		int j = to - 1;
		int x = a[from + (new Random()).nextInt(to - from)];
		while (i <= j) {
			while (a[i] < x) {
				i++;
			}
			while (a[j] > x) {
				j--;
			}
			if (i <= j) {
				int t = a[i];
				a[i] = a[j];
				a[j] = t;
				i++;
				j--;
			}
		}
		quickSort(a, from, j + 1);
		quickSort(a, j + 1, to);
	}

	long mod = 1000000007;

	public long pow(long k) {
		if (k == 0) {
			return 1L;
		}
		if (k == 1) {
			return 2L;
		}
		if (k % 2 == 1) {
			return (2L * pow(k - 1)) % mod;
		}
		long x = pow(k / 2);
		return (x * x) % mod;
	}

	public void solve() {
		long x = in.nextLong();
		if (x == 0) {
			out.println(0);
			return;
		}
		x %= mod;
		long k = in.nextLong();
		long pow = pow(k);
		long ans = 1;
		ans = (ans - pow + mod) % mod;
		ans = (ans + (((2 * pow) % mod) * x) % mod) % mod;
		out.println(ans);
	}

	public void run() {
		try {
			if (systemIO) {
				in = new FastScanner(System.in);
				out = new PrintWriter(System.out);
			} else {
				in = new FastScanner(new File("input.txt"));
				out = new PrintWriter(new File("output.txt"));
