    public static int bsearch(int n,long k)
    {
        int l = 1;
        int r = n;
        while(r>l)
        {
            int mid = (l+r+1)>>1;
            if(pow(2,mid+1)-mid-2<=k)
            {
                l = mid;
            }
            else
            {
                r = mid-1;
            }
        }
        if(pow(2,l+1)-l-2==0&&pow(2,l+1)-l-2==k)
        {
            return 0;
        }
        else if(pow(2,l+1)-l-2<=k)
        {
            return l;
        }
        return 0;
    }
