    {
        long total_max = (pow(4,n)-1)/3;
        long cant_be = ((pow(4,n-steps)-1)/3)*(pow(2,steps+1)-1);
        long available = total_max-cant_be;
        if(available>=k)
        {
            return true;
        }
        return false;
    }
