public class Main {
  static int len(long n) {
    int res = 0;
    while (n > 0) {
      n /= 10;
      res++;
    }
    return res;
  }
  static long big(int len) {
    long p = 1;
    while (len-- > 0) p *= 10;
    return p - 1;
  }
  static long small(int len) {
    return big(len - 1) + 1;
  }
  static long cnt(long n) {
    int len = len(n);
    long cnt = 0;
    for (int l = 1; l < len; l++)
      cnt += 1l * l * (big(l) - small(l) + 1);
    cnt += 1l * len * (n - small(len));
    return cnt;
  }
  public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    long k = sc.nextLong();
    if (k == 1) {
      System.out.println(1);
      return;
    }
    long lo = 1, hi = k, res = 1;
    while(lo <= hi) {
      long mid = lo + hi >> 1L;
      if(cnt(mid) < k) {
        res = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }

    ArrayList<Integer> digits = new ArrayList<>();
    long tmp = res;
    while (tmp > 0) {
      digits.add((int)(tmp % 10));
      tmp /= 10;
    }
//    System.err.println("RES " + res);
//    System.err.println("DIGITS " + digits);
//    System.err.println("Cnt Res " + cnt(res));
    Collections.reverse(digits);
    out.println(digits.get((int)(k - cnt(res) - 1)));
