                long preN = n;
                if(step == 0){
                    k += len;
                    n++;
                }else{
                    k += len * Math.pow(10, step) * 0.9;
                    n += Math.pow(10, step) * 0.9;
                }
                if(k == K || (k >= K && k - K < len)){
                    //System.out.println(k);
                    //System.out.println(n);
                    String nStr = Long.toString(n);
                    System.out.println(nStr.charAt(nStr.length() - (int)(k-K) - 1));
                    return;
                }
                if(K < k){
                    k = preK;
                    n = preN;
                    break;
                }
            }
            step--;
        }
    }
}

