		int max=Math.max(n, m);
		int sum=0,carry=0;
		for(int i=0;i<max;i++){
			int num1=0,num2=0;
			if(n>=i)
			 num1 = Integer.parseInt(str1.charAt(n-i) + "");
			if(m>=i)
			 num2 = Integer.parseInt(str2.charAt(m-i) + "");
			int z = num1 + num2 + carry;
			if (z >= 10) {
				sum = z / 10;
				carry = z % 10;
			} else {
				sum = z;
				carry=0;
			}
			st.add(sum+"");
		}
		StringBuilder sb=new StringBuilder();
		while(!st.isEmpty()){
			sb.append(st.pop());
		}
		return sb+"";
	}
