    static class BSportMafia {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long n = in.nextInt();
            long k = in.nextInt();
            long d = 9 + 4 * (2 * n + 2 * k);
            double smh = Math.sqrt(d);
            double ans = (-3 + smh) / 2;
            out.println(n - (int) ans);
        }

