		long put = n / 2;
		long lower = 0;
		long upper = n;
		while (put * (put + 1) / 2 - (n - put) != k) {
			if (put * (put + 1) / 2 - (n - put) > k) {
				upper = put - 1;
				put = (lower + upper) / 2;
			} else {
				lower = put + 1;
				put = (lower + upper) / 2;
			}
		}
		System.out.println(n - put);

