        boolean[] prime=new boolean[n+1];
        for (int i=2;i<Math.sqrt(n);i++) {
        	for (int j=i+i;j<=n;j=j+i) {
        		prime[j]=true;
        	}
        }
        int size=0;
        for (int i=2;i<=n;i++) {
        	if (!prime[i]) {
        		size++;
        	}
        }
        int[] pn=new int[size];
        int index=0;
        for (int i=2;i<=n;i++) {
        	if (!prime[i]) {
        		pn[index]=i;
        		index++;
        	}        	
        }
        for (int i=2;i<size;i++) {
        	for (int j=0;j<i;j++) {
        		if (pn[i]==pn[j]+pn[j+1]+1) {
//       			System.out.println(pn[i]+"="+pn[j]+"+"+pn[j+1]+"+1");
        			k--;
        		}
        	}
        }
        if (k<=0) {
