		int n = nextInt();
		br.readLine();
		int h = 0, t = 0;
		String s = br.readLine();
		for (int i = 0; i < n; i++) {
			if ((char)s.charAt(i) == 'H') h++; else t++;
		}
		int m = 10001;
		for (int j = 0; j < n; j++) {
			int z = 0;
			for (int i = 0; i < n; i++) {
				if (i + 1 <= h) {
					if (s.charAt((i + j) % n) != 'H') z++;
				} else {
					if (s.charAt((i + j) % n) != 'T') z++;
				}
			}
			if (z < m) m = z;
		}
		out.println(m / 2);
	}

