			if (s[i] == 'T')
				T++;
			else
				H++;
		}

		if (T == 1 || H == 1) {
			out.println(0);
			out.close();
			return;
		}

		b = Arrays.copyOf(a, a.length);
		c = Arrays.copyOf(a, a.length);
