class Pair implements Comparable<Pair>{
    public int a, b;

    Pair(int a, int b){
        this.a = a;
        this.b = b;
    }

    @Override
    public int compareTo(Pair P){
        if(P.b != this.b){
            return b - P.b;
        } else if(P.a == this.a){
            return a - P.a;
        } else{
            return 0;
        }
    }

    public String toString(){
        return a + " " + b;
    }
}

