        if (numChars == -1) 
            throw new InputMismatchException();    
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = mIs.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) 
                return -1;            
        }
        return buf[curChar++];
