	static class Datum
	{
		int[] hs;
		int cost;
		public Datum(int[] hs, int cost) {
			this.hs = hs;
			this.cost = cost;
		}

		public long h()
		{
			long h = 0;
			for(int o : hs){
				h = h * 100 + o;
			}
			return h;
		}
	}

	void solve()
	{
		int n = ni();
		int[] cost = na(4);
		char[][] map = nm(4, n);

		int[] w = new int[4];

		Map<Long, Datum> cans = new HashMap<>();

		outer:
		do{
			for(int i = 0;i < 4;i++){
				if(i+w[i] > 4)continue outer;
			}
			int[] h = new int[4];
			int sc = 0;
			for(int i = 0;i < 4;i++){
				if(w[i] > 0)sc += cost[w[i]-1];
				for(int j = i;j < i+w[i];j++){
					h[j] = Math.max(h[j], w[i]);
				}
			}
			Datum d = new Datum(h, sc);
			long dh = d.h();
			if(!cans.containsKey(dh) || cans.get(dh).cost > sc){
				cans.put(dh, d);
			}
		}while(inc(w, 5));
//		tr(cans.size());

		List<Datum> ds = new ArrayList<>(cans.values());
		long[][][][] dp = new long[4][4][4][4];
		for(int u = 0;u < 4;u++){
			for(int v = 0;v < 4;v++){
				for(int x = 0;x < 4;x++){
					Arrays.fill(dp[u][v][x], Long.MAX_VALUE / 3);
				}
			}
