		dp[0][0][0][0] = 0;
		for(int i = 0;i < n;i++){
			long[][][][] ndp = new long[4][4][4][4];
			for(int u = 0;u < 4;u++){
				for(int v = 0;v < 4;v++){
					for(int x = 0;x < 4;x++){
						Arrays.fill(ndp[u][v][x], Long.MAX_VALUE / 3);
					}
				}
			}

			int[] a = new int[4];
			do{
				long myc = dp[a[0]][a[1]][a[2]][a[3]];
				int[] na = Arrays.copyOf(a, 4);
