    public void solve() throws Exception {
        int n = in.nextInt();
        int a = in.nextInt();
        int b = in.nextInt();
        int c = in.nextInt();
        int T = in.nextInt();

        int[] t = new int[n];
        for (int i = 0; i < n; i++) {
            t[i] = in.nextInt();
        }

        Arrays.sort(t);

        int ans = 0;
        if (b >= c) {
            ans = a * n;
        } else {
            ans = a * n;
            for (int i = 0; i < n; i++) {
                ans += (T - t[i]) * (c - b);
            }
        }

        out.println(ans);
    }

