          }else if (s.charAt(ns - 1) == 'S') {
              if (nS[ns-1] > 0) --nS[ns-1];
              else ++nSr[ns-1];
          }else {
              if (nL[ns-1] > 0) --nL[ns-1];
              else ++nLr[ns-1];
