                    // swap
                    char temp = str1[i+1];
                    str1[i+1] = str1[i];
                    str1[i] = temp;
                    i +=2;
                    continue;
                } else {
                    // flip
                    str1[i] = str2[i];
                    i++;
                    continue;
                }
            }
            i++;
        }
        System.out.println(cost);
    }
}

