        int T=1;
        while(T-->0)
        {
            int n=input.nextInt();
            ArrayList<Integer> adj[]=new ArrayList[n+1];
            Vertex V[]=new Vertex[n+1];
            for(int i=1;i<=n;i++)
            {
                adj[i]=new ArrayList<>();
                V[i]=new Vertex(i);
            }
            for(int i=2;i<=n;i++)
            {
                int v=input.nextInt();
                adj[i].add(v);
