public class TaxiDriversAndLyft {
    PrintWriter out;
    StringTokenizer st;
    BufferedReader br;
    final int imax = Integer.MAX_VALUE, imin = Integer.MIN_VALUE;
    final int mod = 1000000007;

    void solve() throws Exception {
        int t = 1;
//        t = ni();
        for (int ii = 0; ii < t; ii++) {
            int n=ni(), m= ni();
            int[] arr= new int[n+m];
            for (int i = 0; i < n+m; i++) arr[i]=ni();

            int[] val= new int[n+m];
            for(int i=0;i<n+m;i++) val[i]= ni();

            int[] l= new int[n+m];
            int[] r= new int[n+m];
            stack_l(val, l);
            stack_r(val, r);

            int[] ans= new int[n+m];
            for(int i=0;i<n+m;i++) {
                if(val[i]== 1) continue;

                int dist_l= arr[i]- (l[i]!= -1? arr[l[i]]: (int)-1e9);
                int dist_r= (r[i]!= imax? arr[r[i]]: imax)- arr[i];

                if(dist_r< dist_l) ans[r[i]]++;
                else ans[l[i]]++;
            }

            for(int i=0;i<n+m;i++) if(val[i]== 1) out.print(ans[i]+" ");
            out.println();
        }
    }

    public static void main(String[] args) throws Exception {
