       list1=new ArrayList();
       for(int i=0;i<n;i++){
           arr[i]=sc.ni();
           if(arr[i]==1)
           list.add(i);
           else
           list1.add(i);
       }
       boolean res=true;
       if(list1.size()==0)
       res=false;
       else if(list1.size()==1){
        if(arr[list1.get(0)]<list.size()){
            res=false;
        }
        else{
            m=list.size();
            d=2;
            for(int x:list){
                int a=x+1;
                int b=list1.get(0)+1;
                str.append(a+" "+b+"\n");
            }
        }
       }
       else{
            m=list1.size()-1+list.size();
            d=list1.size()-1;
            for(int i=1;i<list1.size();i++){
                int a=list1.get(i)+1;
                int b=list1.get(i-1)+1;
                arr[a-1]--;arr[b-1]--;
                str.append(a+" "+b+"\n");
            }
            int p=0;
            if(p<list.size())
            {
                int a=list.get(p++)+1;
                int b=list1.get(0)+1;
                arr[b-1]--;
                str.append(a+" "+b+"\n");d++;
            }
            if(p<list.size())
            {
                int a=list.get(p++)+1;
                int b=list1.get(list1.size()-1)+1;
                arr[b-1]--;
                str.append(a+" "+b+"\n");d++;
            }
            HashSet<Integer> set=new HashSet();
            for(int x:list1)
                if(arr[x]>0)
                    set.add(x);

            for(int x:set){
                for(;p<list.size();p++){
                    if(arr[x]==0)
                    break;
                    int a=x+1;
                    int b=list.get(p)+1;
                    str.append(a+" "+b+"\n");
                    arr[x]--;
                }
            }
            if(p<list.size())
            res=false;
       }
       if(res){
           pw.println("YES "+d);
           pw.println(m+"\n"+str);
       }
       else
       pw.println("NO");
    }
}

