	static int dfs(int u,int p,int t)
	{
		int ans=0;

		sum[u]=a[u];
		for(int v:adj[u])
			if(v!=p)
			{
				ans+=dfs(v,u,t);
				if(sum[v]>0)
					sum[u]+=sum[v] ;
			}
