            for (int i=n - 1;i>=n / 2;i--)
            {
                if (A[i] > min)
                {
                    A[n - 1 - i] = A[i] - min;
                    A[i] = min;
                    if (n - 1 - i > 0 && A[n - 1 - i] < A[n - i - 2])
                    {
