    public static class Task implements Runnable {
        final FastIO io;
        final Debug debug;
        int inf = (int) 1e8;

        public Task(FastIO io, Debug debug) {
            this.io = io;
            this.debug = debug;
        }

        @Override
        public void run() {
            solve();
        }

        BIT bit;
        int n;
        int k;

        public void solve() {
            n = io.readInt();
            k = io.readInt();
            char[] status = new char[n + 1];
            char[] revStatus = new char[n + 1];
            io.readString(status, 1);
            for (int i = 1; i <= n; i++) {
                revStatus[i] = status[i] == '1' ? '0' : '1';
            }

            bit = new BIT(n);
            for (int i = 1; i <= n; i++) {
                bit.update(i, status[i] - '0');
            }
            for (int i = 1; i + k - 1 <= n; i++) {
                int sum = bit.query(i - 1)
                        + bit.query(n) - bit.query(i + k - 1);
                if (sum == 0 || sum == n - k) {
                    io.cache.append("tokitsukaze");
                    return;
                }
            }

            //quailty win case
            if (solve0(status) && solve0(revStatus)) {
                io.cache.append("quailty");
                return;
            }
            io.cache.append("once again");
        }

        public boolean solve0(char[] status) {
            TreeSet<Integer> pos = new TreeSet<>();
            for (int i = 1; i < status.length; i++) {
                if (status[i] == '0') {
                    pos.add(i);
                }
            }
            for (int i = 1; i + k - 1 <= n; i++) {
                int l = i;
                int r = i + k - 1;
                int firstZero = pos.first();
                if (firstZero >= l && firstZero <= r) {
                    firstZero = pos.ceiling(r + 1);
                }
                int lastZero = pos.last();
                if (lastZero >= l && lastZero <= r) {
                    lastZero = pos.floor(l - 1);
                }
                if (lastZero - firstZero + 1 > k) {
                    return false;
                }
            }
            return true;
        }
    }


    /**
     * Created by dalt on 2018/5/20.
     */
    public static class BIT {
        private int[] data;
        private int n;

        /**
         * 创建大小A[1...n]
         */
        public BIT(int n) {
            this.n = n;
            data = new int[n + 1];
        }

        /**
         * 查询A[1]+A[2]+...+A[i]
         */
        public int query(int i) {
            int sum = 0;
            for (; i > 0; i -= i & -i) {
                sum += data[i];
            }
            return sum;
        }

        /**
         * 将A[i]更新为A[i]+mod
         */
        public void update(int i, int mod) {
            for (; i <= n; i += i & -i) {
                data[i] += mod;
            }
        }

        /**
         * 将A全部清0
         */
        public void clear() {
            Arrays.fill(data, 0);
        }

        @Override
        public String toString() {
            StringBuilder builder = new StringBuilder();
            for (int i = 1; i <= n; i++) {
                builder.append(query(i) - query(i - 1)).append(' ');
            }
            return builder.toString();
        }
    }


