    static class BPhoenixAndPuzzle {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            if (n % 2 == 1) {
                out.println("NO");
                return;
            }
            n /= 2;
            if (n == 1 || (int) Math.sqrt(n) * (int) (Math.sqrt(n)) == n) {
                out.println("YES");
            } else {
                if (n % 2 == 0) {
                    n /= 2;
                    if ((int) Math.sqrt(n) * (int) (Math.sqrt(n)) == n) {
                        out.println("YES");
                        return;
                    }
                }
                out.println("NO");
            }
        }

    }

