        public Entity(int x, int a) {
            this.x = x;
            this.a = a;
        }
        public int x, a;

        public int compareTo(Object t) {
            Entity o = (Entity) t;
            return x == o.x ? 0 : x < o.x ? -1 : 1;
        }
