	}

	double nextDouble() {
		return sc.nextDouble();
	}

	void solve() {
		int n = nextInt();
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = nextInt();
		}
		Arrays.sort(a);
		int i = 1;
		while (i < n && a[i] == a[i - 1]) {
			++i;
		}
		if (i >= n) {
			out.println("NO");
		} else {
			out.println(a[i]);
		}
	}
}

