        Integer[]a = new Integer[n+1];
        for (int i = 1; i <= n; i++) {
            a[i] = nextInt();
        }
        if (k==1) {
            System.out.println(n);
            return;
        }
        Arrays.sort(a, 1, n+1);
        Set<Integer> set = new HashSet<Integer>();
        int ans = 0;
        int INF = (int) 1e9;
        for (int i = 1; i <= n; i++) {
            if (set.contains(a[i]))
