	void solve() throws IOException {
		int w = readInt();
		int h = readInt();

		TreeSet<Integer> xCuts = new TreeSet<Integer>();
		xCuts.add(0);
		xCuts.add(w);

		TreeSet<Integer> yCuts = new TreeSet<Integer>();
		yCuts.add(0);
		yCuts.add(h);

		TreeMap<Integer, Integer> wMultiSet = new TreeMap<Integer, Integer>();
		TreeMap<Integer, Integer> hMultiSet = new TreeMap<Integer, Integer>();

		inc(wMultiSet, w);
		inc(hMultiSet, h);

		int n = readInt();
		while (n --> 0) {
			String type = readString();
			int coordinate = readInt();

			if (type.equals("H")) {
				int y = coordinate;

				int leftY = yCuts.floor(y);
				int rightY = yCuts.ceiling(y);

				int delta = rightY - leftY;
				dec(hMultiSet, delta);

				yCuts.add(y);
				inc(hMultiSet, y - leftY);
				inc(hMultiSet, rightY - y);
			} else {
				int x = coordinate;

				int leftX = xCuts.floor(x);
				int rightX = xCuts.ceiling(x);

				int delta = rightX - leftX;
				dec(wMultiSet, delta);

				xCuts.add(x);
				inc(wMultiSet, x - leftX);
				inc(wMultiSet, rightX - x);
			}

			long maxWDelta = wMultiSet.lastKey();
			long maxHDelta = hMultiSet.lastKey();

			out.println(maxWDelta * maxHDelta);
		}
	}

	void inc(Map<Integer, Integer> multiSet, int value) {
		Integer count = multiSet.get(value);
		if (count == null) {
			multiSet.put(value, 1);
		} else {
			multiSet.put(value, count + 1);
		}
	}

	void dec(Map<Integer, Integer> multiSet, int value) {
		Integer count = multiSet.get(value);
		if (count == 1) {
			multiSet.remove(value);
		} else {
			multiSet.put(value, count - 1);
		}
	}
}

