        long[] arr = nextLongArr(n);
        long[] diff = new long[n];
        long presum = 0;
        for (int i = n - 1; i >= 0; i--) {
            diff[i] = presum - (n - i - 1) * arr[i];
            presum += arr[i];
        }

        BigInteger pairs = new BigInteger("0");
        for (long s : diff) {
            pairs = pairs.add(new BigInteger(Long.toString(s)));
