		int[] xs = new int[3*n];
		for(int i = 0;i < n;i++){
			xs[3*i] = a[i];
			xs[3*i+1] = a[i]-1;
			xs[3*i+2] = a[i]+1;
		}
		xs = shuffle(xs, new Random());
		int[] imap = shrinkX(xs);

		BigInteger ans = BigInteger.valueOf(0L);

		{
			int[] ft = new int[3*n+3];
			for(int i = 0;i < n;i++){
				int y = Arrays.binarySearch(imap, a[i]);
				int num = 
						i - sumFenwick(ft, y + 1) + sumFenwick(ft, y - 2);
				ans = ans.add(BigInteger.valueOf((long)a[i] * num));
				addFenwick(ft, y, 1);
			}
		}

