    long[][] pow(long[][] mat, long val) {
        if (val == 1)
            return mat;
        if (val % 2 == 0) {
            long[][] m = pow(mat, val / 2);
            return mul(m, m);
        } else {
            val--;
            long[][] ss = mat.clone();
            return mul(pow(mat, val), ss);
        }
    }

    long[][] mul(long[][] m1, long[][] m2) {
        int a1 = m1.length, a2 = m1[0].length, a3 = m2[0].length;
        long[][] ff = new long[a1][a3];
        for (int i = 0; i < a1; i++) {
            for (int j = 0; j < a3; j++)
                for (int s = 0; s < a2; s++)
                    ff[i][j] = (ff[i][j] + m1[i][s] * m2[s][j]) % mo;
        }
        return ff;
    }

