        checked[cur] = true;
        for (int i = 0; i < tree[cur].size(); i += 2) {
            if (!checked[tree[cur].get(i)]) {
                dfs(tree[cur].get(i), a, b, c);
                a[cur] = Math.max(a[cur], b[tree[cur].get(i)] + tree[cur].get(i + 1) - c[tree[cur].get(i)]);
                b[cur] += c[tree[cur].get(i)];
            }
        }
