        if (dp[i][j] == 0)
            return;
        if (dp[i - 1][j] == dp[i][j])
            find(i - 1, j, ans, dp, w);
        else {
            ans.add(i);
            find(i - 1, j - w[i - 1], ans, dp, w);
        }
    }

