        int n=sc.ni();
        int[] arr=new int[n];
        for(int i=0;i<n;i++)
        arr[i]=sc.ni();
        invcount(arr,0,n-1);
        n%=2;
        ans%=2;
        if(n==ans)
        pw.print("Petr");
        else
        pw.print("Um_nik");
    }
    public ArrayList<Integer> invcount(int[] arr,int l,int r){
        if(r<=l){
         ArrayList<Integer> list = new ArrayList();
         list.add(arr[l]);
         return list;}
        int mid=(l+r)/2,p=0,q=0;
        ArrayList<Integer> list=invcount(arr,l,(l+r)/2);
        ArrayList<Integer> list1=invcount(arr,(l+r)/2+1,r);
        ArrayList<Integer> ret=new ArrayList();
        while(list1.size()>q&&list.size()>p){
            if(list.get(p)<list1.get(q))
            ret.add(list.get(p++));
            else{
                ans=(ans+(list.size()-p)%2)%2;
                ret.add(list1.get(q++));
            }
        }
        while(p<list.size())
        ret.add(list.get(p++));
        while(q<list1.size())
        ret.add(list1.get(q++));
        return ret;
    }
