                res[next.to] = (next.same == 1 ? 1 : -1) * res[node];
                dfs(next.to);
            }
        }

        public boolean ok(int mask, ArrayList<TaskC.Vector> vs, OutputWriter out) {
            long x = 0, y = 0;
            for (int i = 0; i < vs.size(); i++) {
                if (((mask >> i) & 1) == 1) {
                    x += vs.get(i).x;
                    y += vs.get(i).y;
                } else {
                    x -= vs.get(i).x;
                    y -= vs.get(i).y;
                }
            }
            if (ok2(x, y)) {
                res = new int[n];
                for (int i = 0; i < vs.size(); i++) {
                    if (((mask >> i) & 1) == 1) {
                        res[vs.get(i).id] = +1;
                    } else {
                        res[vs.get(i).id] = -1;
                    }
                    dfs(vs.get(i).id);
                }
                out.println(res);
                return true;
            }
            return false;
        }

