            while (vs.size() > 10) {
                vs.sort(Comparator.comparingDouble(x -> Math.atan2(x.y, x.x)));
                ArrayList<TaskC.Vector> nvs = new ArrayList<>();
                for (int i = 0; i < vs.size(); i++) {
                    if (i + 1 < vs.size()) {
                        TaskC.Vector a1 = vs.get(i);
                        TaskC.Vector a2 = vs.get(i + 1);
