                            } else {
                                nvs.add(new TaskC.Vector(a2.x - a1.x, a2.y - a1.y, a2.id));
                                graph[a2.id].add(new TaskC.Edge(a1.id, 0));
                            }
                            i++;
                        } else {
                            nvs.add(vs.get(i));
                        }
                    } else {
                        nvs.add(vs.get(i));
                    }
                }
                vs = nvs;
            }

