public class Codeforces
{
    public static void main(String args[])throws Exception
    {
        BufferedReader bu=new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb=new StringBuilder();
        int t=Integer.parseInt(bu.readLine());
        while(t-->0)
        {
            int n=Integer.parseInt(bu.readLine());
            String s[]=bu.readLine().split(" ");
            HashMap<Integer,Integer> hm=new HashMap<>();
            ArrayList<Integer> sides=new ArrayList<>();
            int i,x;
            for(i=0;i<n;i++)
            {
                x=Integer.parseInt(s[i]);
                hm.put(x,hm.getOrDefault(x,0)+1);
            }
            for(int y:hm.keySet())
            if(hm.get(y)>1)
            {
                sides.add(y);
                if(hm.get(y)>3) sides.add(y);
            }
            Collections.sort(sides);
            double min=Integer.MAX_VALUE; int minp=1;
            for(i=1;i<sides.size();i++)
            {
                int l=sides.get(i),r=sides.get(i-1);
                double v=1.0*l/r+1.0*r/l;
                if(v<min)
                {
                    min=v;
                    minp=i;
                }
            }
            int a1=sides.get(minp),a2=sides.get(minp-1);
            sb.append(a1+" "+a1+" "+a2+" "+a2+"\n");
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String args[])throws Exception
    {
        BufferedReader bu=new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb=new StringBuilder();
        int t=Integer.parseInt(bu.readLine());
        while(t-->0)
        {
            int n=Integer.parseInt(bu.readLine());
            String s[]=bu.readLine().split(" ");
            HashMap<Integer,Integer> hm=new HashMap<>();
            ArrayList<Integer> sides=new ArrayList<>();
            int i,x;
            for(i=0;i<n;i++)
            {
                x=Integer.parseInt(s[i]);
                hm.put(x,hm.getOrDefault(x,0)+1);
            }

            /*
            rectangles need to be formed
            so, what do we do? we take all distinct equal pairs, because only equal pairs can form rectangles
            for any rectangle, p=2(a+b), s=ab
            p^2/s=4(a^2+b^2+2ab)/ab=4(a/b+b/a+2)
            hence we need smallest a/b+b/a
            now fix a, a/b+b/a will be smallest for the nearest value smaller or larger than a
            hence its is reduced to a simple sorting problem where all we gotta do is find smallest a/b+b/a for consecutive pairs
            (ans is always possible)  
             */
            for(int y:hm.keySet())
            if(hm.get(y)>1)
            {
                sides.add(y);
                if(hm.get(y)>3) sides.add(y);
            }
            Collections.sort(sides);
            double min=Integer.MAX_VALUE; int minp=1;
            for(i=1;i<sides.size();i++)
            {
                int l=sides.get(i),r=sides.get(i-1);
                double v=1.0*l/r+1.0*r/l;
                if(v<min)
                {
                    min=v;
                    minp=i;
                }
            }
            int a1=sides.get(minp),a2=sides.get(minp-1);
            sb.append(a1+" "+a1+" "+a2+" "+a2+"\n");
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.Random;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Function;

public class Main {

    static int T;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        T = sc.nextInt();

        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < T; i++) {
            int n = sc.nextInt();
            int[] a = sc.nextIntArray(n);
            int[] ans = solve(n, a);
            StringJoiner j = new StringJoiner(" ");
            for (int each : ans) {
                j.add(String.valueOf(each));
            }
            pw.println(j.toString());
        }
        pw.flush();
    }

    static int[] solve(int N, int[] A) {
        // a/b が1に近いものを探す
        shuffle(A);
        Arrays.sort(A);
        int cur = A[0];
        int time = 1;
        double r = 0;
        int prev = -1;
        int a = -1;
        int b = -1;
        for (int i = 1; i < N; i++) {
            if( cur == A[i] ) {
                time++;

                if( time == 2 ) {
                    if( prev != -1 ) {
                        double r1 = (double)prev/cur;
                        if( r1 > r ) {
                            r = r1;
                            a = prev;
                            b = cur;
                        }
                    }
                    prev = cur;
                }

                if( time == 4 ) {
                    return new int[]{cur, cur, cur, cur};
                }

            } else {
                time = 1;
                cur = A[i];
            }
        }

        return new int[]{a, a, b, b};
    }

    static void shuffle(int[] a) {
        Random r = ThreadLocalRandom.current();
        for (int i = a.length-1; i >= 0; i--) {
            int j = r.nextInt(i+1);
            int t = a[i];
            a[i] = a[j];
            a[j] = t;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.math.BigInteger;
  import java.util.*;

  public class A {
      public static void main(String[] args) {
          Scanner io = new Scanner(System.in);
          int n = io.nextInt(), a = io.nextInt();
          BigInteger bigA = new BigInteger(a + "");
          long[] b = new long[n];
         int[] c = new int[n];
         long[] pow = new long[15];
         String[] pow2 = new String[15];
         HashSet<Integer> set = new HashSet<>();
         pow[0] = 1;
         pow2[0] = "";
         for (int i = 1; i < pow.length; i++) {
             pow[i] = pow[i - 1] * 10;
             pow2[i] = pow2[i - 1] + "0";
         }
         long ans = 0;

         for (int i = 0, t; i < n; i++) {
             t = io.nextInt();
             b[i] = t % a;
             c[i] = (t + "").length();
             set.add(c[i]);
         }

         HashMap<Long, Long>[] map = new HashMap[pow.length];
         for (int l : set) {
             map[l] = new HashMap();
             for (int i = 0; i < n; i++) {
                 long m = (1L * (b[i] % a) * pow[l] % a);
                 if (m < 0) {
                     BigInteger big = new BigInteger(b[i] + pow2[l]);
                     m = big.mod(bigA).longValue();
                 }
                 map[l].put(m, map[l].getOrDefault(m, 0L) + 1);
             }
         }

         for (int i = 0; i < n; i++) {
             long find = b[i] == 0 ? 0 : a - b[i];
             if (!map[c[i]].containsKey(find)) continue;
             long cnt = map[c[i]].get(find);
             long t = 1L * (b[i] % a) * pow[c[i]] % a;
             if (t < 0) {
                 BigInteger big = new BigInteger(b[i] + pow2[c[i]]);                 t = big.mod(bigA).longValue();
             }
             //减去（a1+“”+a1）%mod的贡献
             if (t == find) cnt--;
             ans += cnt;
         }
         System.out.println(ans);
     }
}

