        al.add(1);
        boolean pos=true;
        while(!al.isEmpty())
        {
            ArrayList<Integer> nal=new ArrayList<>();
            for(int x:al)
            {
                int ch=g[x].size()-1,j;
                for(j=0;j<ch;j++)
                {
                    vis[a[i]]=true;
                    nal.add(a[i++]);
                }

                for(int y:g[x])
