        int x_max = Math.max(Math.max(dx0, dx1), dx2);
        int dy0 = Math.abs(p[0][1] - p[1][1]);
        int dy1 = Math.abs(p[1][1] - p[2][1]);
        int dy2 = Math.abs(p[2][1] - p[0][1]);
