        if(k==len)return 0;
        int[] diff = new int[len-1];
        for(int i=0;i<len-1;i++){
            diff[i] += -arr[i+1]+arr[i];
        }

        Arrays.sort(diff);
        for(int i=0;i<k-1;i++){
            res+=diff[i];
        }
        return res;
    }
