						4 * r * r - (finalpoints.get(j).x - centers.get(i)) * (finalpoints.get(j).x - centers.get(i)))
						+ finalpoints.get(j).y;
				if(dist > maxy)
					maxy = dist;
			}

			pw.print(maxy + " ");
			finalpoints.add(new Point(centers.get(i), maxy));
		}

		pw.close();
	}

