			long[][] dp = new long[N+1][N+1];

			for(int i=0;i<N;i++){
				if(i==0){
					dp[i][0] = 1;
				}
				else if(A[i-1]!=1){
					dp[i][N] = dp[i-1][N];
					for(int j=N-1;j>=0;j--){
						/* sum of all positions from */
						dp[i][j] = (dp[i-1][j] + dp[i][j+1])%MOD;
