            for (int i = 0; i < n; i++) {
                ar[i] = in.readString().charAt(0);
            }
            long dp[][] = new long[n + 1][n + 1];
            for (int i = 0; i < n; i++) {
                dp[n - 1][i] = 1;
            }
            long prev = n;
            for (int i = n - 2; i >= 0; i--) {
