                            dp[i][j] = dp[i + 1][j + 1];
                        }
                    } else {
                        for (int j = n - 2; j >= 0; j--) {
                            dp[i][j] = dp[i + 1][j + 1];
                        }

                    }
                } else {
                    for (int j = n - 1; j >= 0; j--) {
                        if (prev < 0) {
                            prev += mod;
                        }
                        dp[i][j] = prev;
                        prev = prev - dp[i + 1][j];
                    }
                }
                prev = 0;
                for (int j = 0; j < n; j++) {
                    prev += dp[i][j];
                    prev = prev % mod;
                }
            }
