			long heightCache = 0;
			for (int height = n-1; height >= 0; height--) {
				if (isPreviousFor) {
					array[idx + 1][height + 1] += array[idx][height];
					array[idx + 1][height + 1] %= MOD;
				} else {
					heightCache += array[idx][height];
					heightCache %= MOD;
					array[idx + 1][height] += heightCache;
					array[idx + 1][height] %= MOD;
				}
			}
			isPreviousFor = isFor[idx];
		}
