            int swap = 0;
            for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) if (a[i] > a[j]) swap ^= 1;

            int m = in.readInt();
            while (m-- > 0) {
                int l = in.readInt();
                int r = in.readInt();
                int s = (r - l + 1);
                s = s * (s - 1) / 2;
                swap ^= s;
                out.println((swap & 1) == 0 ? "even" : "odd");
            }
        }

    }

