			int diff=end-start;
			boolean evenChange=(diff+1)/2%2==0;
			even^=!evenChange;
			System.out.println(even?"even":"odd");
		}
	}

	private static int countInversions(int[] a) {
		int c=0;
		for (int i=0; i<a.length; i++) {
			for (int j=i+1; j<a.length; j++)
				if (a[j]<a[i])
					c++;
		}
		return c;
	}





