		for (int i = 0; i < n; i++)
			arr[i] = scan.nextInt();
		int inv = 0;
		for (int i = 0; i < n; i++)
		{
			for (int j = i+1; j < n; j++)
			{
				if (arr[i] > arr[j])
					inv++;
			}
		}
		inv &= 1;

		int[] cumul = new int[n+1];
		for (int i = 2; i < cumul.length; i++)
		{
			cumul[i] = cumul[i-1] + i-1;
		}
