     public static void solve(){

        long[] dp = new long[n];
        dp[n-1] = mx;
        dp[0] = dp[n-1];
        for(int i = n-2 ; i > 0 ; i--){
            dp[i] = mx;
            for(int j = i+1 ; j < n; j++){
                if(arr[j] <= arr[i])
                    continue;
                dp[i] = Math.min(dp[i],darr[i] + darr[j]);
            }
        }
        long ans = mx*8;
        for(int i = 0 ; i < n-1 ; i++){
            long local = mx*8;
            for(int j = i+1 ; j < n-1 ; j++){
                if(arr[j] <= arr[i])
                    continue;
                local = Math.min(local,darr[i]+dp[j]);
            }
            ans = Math.min(ans,local);
        }
        if(ans >= mx){
            System.out.println(-1);
            return;
        }
        System.out.println(ans);

     }

