        };
        boolean possible = true;
        for(int[] d: dir){
            int x = d[0]+i,y=d[1]+j;
            if(x >= mat.length || y >= mat[0].length || x < 0 || y < 0){
                possible = false;
                break;
            }
            if(mat[x][y] == 0)
                possible = false;
        }
        return possible;
    }

