		out.println((list[ind][0][0] + 1) + " " + (list[ind][0][1] + 1));

		for(int i = 1; i < list[ind].length; i++) {
			if(list[ind][i][0] > last) {
				out.println((list[ind][i][0] + 1) + " " + (list[ind][i][1] + 1));
				last = list[ind][i][1];
