        int n=v.length;
        if(n==0) return;
        int dp[]=new int[n+1];
        int prev[]=new int[n+1];
        int mx[]=new int[n+1];
        int mxid[]=new int[n+1];
        for(int i=1;i<=n;i++){
            Node p=v[i-1];
            dp[i]=dp[i-1];
            prev[i]=-1;
            int l=1,r=i-1;
            int idx=0;
            while(l<=r){
                int mid=(l+r)>>1;
                if(v[mid-1].r<p.l){
                    idx=mid;
                    l=mid+1;
                }else r=mid-1;
            }
            if(1+mx[idx]>dp[i]){
                dp[i]=1+mx[idx];
                prev[i]=mxid[idx];
            }
            mx[i]=mx[i-1];
            mxid[i]=mxid[i-1];
            if(dp[i]>mx[i]){
                mx[i]=dp[i];
                mxid[i]=i;
            }


        }
        if (dp[n] > cnt){
            cnt=dp[n];
            ans.clear();
            int id=n;
            while(id>0){
                if(dp[id]==dp[id-1]){
                    id--;
                    continue;
                }
                ans.add(new Node(v[id-1].l,v[id-1].r));
