    static int fun(int pos, int[] dp, ArrayList<Node> rangeList, int[] bactTrack){

        if(pos==rangeList.size()-1){
            bactTrack[pos]=-1;
            return 0;

        }

        if(dp[pos]!=-1){
            return dp[pos];
        }

        int i=pos+1;
        int maxAns=0;
        int nextPos=-1;
        for(;i<=rangeList.size()-1;i++){


            if(rangeList.get(i).l>rangeList.get(pos).r){
                int tempAns=1+fun(i, dp,rangeList, bactTrack);
                if(tempAns>maxAns){
                    maxAns=tempAns;
                    nextPos=i;
                }
            }
        }

        dp[pos]=maxAns;
        bactTrack[pos]=nextPos;
        return maxAns;




    }

    static class Node implements Comparable<Node>{
        int l;
        int r;

        public Node(int l, int r) {
            this.l = l;
            this.r = r;
        }




        @Override
        public int compareTo(Node o2) {
            if(this.l!=o2.l){
                return this.l-o2.l;
            } else{
                return this.r-o2.r;
            }
        }

    }
