					List<Interval> ints = mp.get(s);
					if(ints==null) ints = new ArrayList<Interval>();
					if(ints.size()==0 || ints.get(0).l>j) {
						ints.add(0,inter);
					}
					if(ints.size()>max) {
						max = ints.size();
						maxId = s;
					}
					mp.put(s, ints);
//				}
				if(j<n-1) prev =  a[j+1]-a[j];
			}
		}
		List<Interval> l = mp.get(maxId);
		ret.append(l.size()+ "\n");
		for(Interval inter : l) {
			ret.append((inter.l+1) + " " + (inter.r+1) + "\n");
		}
		return ret;
	}

}

