class pair
{
	int l;
	int r;

	public pair(int l,int r)
	{
		this.l=l;
		this.r=r;
	}
}

class comp implements Comparator<pair>
{
	public int compare(pair a,pair b)
	{
		if(a.r<b.r)
			return -1;
		else if(a.r==b.r)
		{
			return b.l-a.l;
		}
		else
			return 1;
	}
