		for (int i = 1; i <= n; i++)
			for (int j = i; j <= n; j++)
				vv[m++] = new V(i, j, aa[j] - aa[i - 1]);
		Arrays.sort(vv, (u, v) -> u.a != v.a ? u.a - v.a : u.r - v.r);
		int[] ii_ = new int[m];
