        char[] temp2 = new char[(int) 2e5 + 3];
        char[] temp3 = new char[(int) 2e5 + 3];
        for (int i = 0; i < (int) 2e5 + 3; i++) {
            if (i % 3 == 0) temp1[i] = 'R';
            if (i % 3 == 1) temp1[i] = 'G';
            if (i % 3 == 2) temp1[i] = 'B';
            if (i % 3 == 0) temp2[i] = 'G';
            if (i % 3 == 1) temp2[i] = 'B';
            if (i % 3 == 2) temp2[i] = 'R';
            if (i % 3 == 0) temp3[i] = 'B';
            if (i % 3 == 1) temp3[i] = 'R';
            if (i % 3 == 2) temp3[i] = 'G';
        }

        while (q-- > 0) {
            int n = in.nextInt();
            int k = in.nextInt();
            String str = in.next();

            int[] dp1 = new int[n];
            int[] dp2 = new int[n];
            int[] dp3 = new int[n];
            for (int i = 0; i < n; i++) {
                if (str.charAt(i) != temp1[i]) dp1[i]++;
                if (str.charAt(i) != temp2[i]) dp2[i]++;
                if (str.charAt(i) != temp3[i]) dp3[i]++;
            }
            for (int i = 1; i < n; i++) {
                dp1[i] += dp1[i-1];
                dp2[i] += dp2[i-1];
                dp3[i] += dp3[i-1];
            }
