        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int arr[] = in.nextIntArray(n);
            Arrays.sort(arr);
            int ans = 0;
            for (int i = 0; i < n; i++) {
                if (arr[i] == -1)
                    continue;
                else {
                    //out.println(arr[i]);
                    ans++;
                    for (int j = i + 1; j < n; j++) {
