            int n = sc.nextInt();
            ArrayList<Stack<Integer>> ar = new ArrayList<Stack<Integer>>();
            for (int j = 0; j < n + 1; j++) {
                ar.add(new Stack<Integer>());
            }
            HashMap <Integer , Integer> hm = new HashMap<Integer, Integer>();
            StringBuilder cur = new StringBuilder();
            int l = 0;
            for (int j = 0; j < n; j++) {
                int a = sc.nextInt();
                if( a == 1)
                {
                    if(cur.length() == 0)
                        cur.append("1");
                    else
                        cur.append(".1");
                    l++;
