    static class TaskC1 {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int numTests = in.nextInt();
            for (int test = 0; test < numTests; test++) {
                int n = in.nextInt();
                int[] a = new int[n];
                for (int i = 0; i < n; i++) {
                    a[i] = in.nextInt() - 1;
                }

                int[] path = new int[n];
                int p = 0;
                for (int i = 0; i < n; i++) {
                    if (a[i] == 0) {
                        path[p++] = 0;
                    } else {
                        while (path[p - 1] + 1 != a[i]) {
                            --p;
                        }
                        ++path[p - 1];
                    }
                    for (int j = 0; j < p; j++) {
                        if (j > 0) {
                            out.print(".");
                        }
                        out.print(path[j] + 1);
                    }
                    out.println();
                }
            }
        }

    }

