		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		while(t-->0) {
			ArrayList<Integer> al = new ArrayList<>();
			Map<Integer,Integer> map = new HashMap<>();
			int n = sc.nextInt();
			int a[] = new int[n];
			for(int i=0;i<n;i++) {
				a[i] = sc.nextInt();
			}
			Stack<Integer> st = new Stack<>();
			StringBuilder sb = new StringBuilder();
			for(int i=0;i<n;i++) {
				if(a[i]==1) st.push(1);
				else {
					while(st.peek()!=(a[i]-1)) {
						st.pop();
						if(st.isEmpty()) break;
					}
					if(st.isEmpty()) st.push(a[i]);
					else {
						st.pop();
						st.push(a[i]);
					}
				}
				Stack<Integer> temp =  new Stack<>();
				while(!st.isEmpty()) {
					temp.push(st.peek());
					st.pop();
				}
				while(!temp.isEmpty()) {
					sb.append(temp.peek()+".");
					st.push(temp.peek());
					temp.pop();
				}
				sb.deleteCharAt(sb.length()-1);
				sb.append("\n");
			}
			System.out.println(sb);
		}
	}
}

