public class C {
  static FastScanner sc = new FastScanner(System.in);

  public static void main(String[] args) {
    try (PrintWriter out = new PrintWriter(System.out)) {
      int T = sc.nextInt();
      for (int tt = 1; tt <= T; tt++) {
        int n = sc.nextInt();
        Stack<Integer> stack = new Stack<>(); //index of probable entries from ans for next  which are on stack
        stack.push(0);
        List<List<Integer>> ans = new ArrayList<>();
        ans.add(Arrays.asList(1));
        int temp = sc.nextInt();
        for (int i = 1; i < n; i++) {
          int nxt = sc.nextInt();
          if (nxt == 1) {
            List<Integer> nxtItem = new ArrayList<>(ans.get(stack.peek()));
            nxtItem.add(1);
            ans.add(nxtItem);
            stack.push(i);
          } else {
            while (ans.get(stack.peek()).get(ans.get(stack.peek()).size() - 1) != nxt - 1) {
              stack.pop();
            }
            List<Integer> nxtItem = new ArrayList<>(ans.get(stack.peek()));
            nxtItem.set(nxtItem.size() - 1, nxt);
            ans.add(nxtItem);
            stack.pop();
            stack.push(i);
          }
        }
        printAns(ans);
      }
    }
  }

  private static void printAns(List<List<Integer>> ans) {
    for (List<Integer> list : ans) {
      for (int i = 0; i < list.size(); i++) {
        if (i == list.size() - 1)
          System.out.println(list.get(i));
        else
          System.out.print(list.get(i) + ".");
      }
    }
  }

  static class FastScanner {
