			int tmp = arr[i];
			arr[i] = arr[j];
			arr[j] = tmp;
		}
		Arrays.sort(arr);
	}

	static ArrayList<Integer> sieve(int n) {
		ArrayList<Integer> primes = new ArrayList<>();
		boolean[] isPrime = new boolean[n];
		Arrays.fill(isPrime, true);
		isPrime[0] = isPrime[1] = false;
		for (int i = 2; i * i <= n; i++) {
			if (isPrime[i]) {
				for (int j = i * i; j < n; j += i) {
					isPrime[j] = false;
				}
			}
		}
		for (int i = 2; i < n; i++) {
			if (isPrime[i])
				primes.add(i);
		}
		return primes;
	}

