		int t = sc.nextInt();
		int i,j;
		for(i=0; i<t; i++) {
			int n = sc.nextInt();
			int arr[] = new int[n];
			for(j=0; j<n; j++) {
				arr[j] = sc.nextInt();
			}
			String[] str = makeList(arr);
			for(j=0; j<n; j++) {
				System.out.println(str[j]);
			}
		}
		sc.close();
	}
	static String[] makeList(int[] arr) {
		int n = arr.length;
		int i,j,m,lastIdx;
		String str[] = new String[n];
		str[0] = "" + arr[0];
		for(i=1; i<n; i++) {
			m = str[i-1].length();
			j=m-1;
			lastIdx=m;
			str[i] = "";
			if(arr[i] == 1) {
				str[i] = str[i-1] + ".1";
				continue;
			}
			while(j >=0) {
				while(j>=0 && str[i-1].charAt(j) != '.')
					j--;
				if(arr[i] - Integer.parseInt(str[i-1].substring(j+1, lastIdx)) == 1) {
					str[i] = str[i-1].substring(0,j+1) + arr[i];
					break;
				}
				lastIdx = j;
				j--;
			}
		}
		return str;
	}
