	private static void add(Stack<Integer> stack, int num) {
		if(stack.isEmpty()) {
			stack.add(num);
			return;
		}
		if(num == 1) {
			stack.add(num);
			return;
		}
		while(!stack.isEmpty()) {
			int curr = stack.pop();
			if(curr + 1 == num) {
				break;
			}
		}
		stack.add(num);
	}


	public static void printStack(Stack<Integer> stack, PrintWriter out) {
		Stack<Integer> stack2 = new Stack<>();
		StringBuilder sb = new StringBuilder();
		while(!stack.isEmpty()) {
			stack2.add(stack.pop());
		}
		while(!stack2.isEmpty()) {
			int num = stack2.pop();
			if(stack2.isEmpty()) {
				sb.append(num+"");
			}
			else {
				sb.append(num + ".");
			}
			stack.add(num);
		}
		out.println(sb.toString());
	}

