    public static int[] zalgo(String str){
        int n = str.length();
        int[] z = new int[n];
        int L = 0, R = 0;
        for (int i = 1; i < n; i++) {
          if (i > R) {
            L = R = i;
            while (R < n && str.charAt(R-L) == str.charAt(R)) R++;
            z[i] = R-L; R--;
          } else {
            int k = i-L;
            if (z[k] < R-i+1) z[i] = z[k];
            else {
              L = i;
              while (R < n && str.charAt(R-L) == str.charAt(R)) R++;
              z[i] = R-L; R--;
            }
          }
        }
        return z;
    }

