		out.flush();
	    }

	} finally {
	    in.close();
	    out.close();
	}
    }

    private static void solve() {
	final String s = in.next();

	int ans = 0;
	for (int l = 0; l < s.length(); ++l) {
	    for (int r = l; r < s.length(); ++r) {
