        Queue<Integer> q = new LinkedList<Integer>();

        for (int i = 0; i < k; i++) {

            int x = sc.nextInt() - 1;

            int y = sc.nextInt() - 1;

            q.add(x);

            q.add(y);

            v[x][y] = true;

        }

        int lastx = 0;

        int lasty = 0;

