    public static void main(String[] args) throws IOException {
		System.setIn(new FileInputStream("input.txt"));
		System.setOut(new PrintStream("output.txt"));
        BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
		String s[] = r.readLine().split("\\s+");
		int n = Integer.parseInt(s[0]);
		int m = Integer.parseInt(s[1]);
		int k = Integer.parseInt(r.readLine());
		int[][] a = new int[n][m];
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++)
				a[i][j] = Integer.MAX_VALUE;
		}
		assert k >= 1 && k < n * m;
		int max = 0;
		StringTokenizer st = new StringTokenizer(r.readLine());
		assert st.countTokens() == k;
		for(; k > 0; k--) {
			int x = Integer.parseInt(st.nextToken()) - 1;
			int y = Integer.parseInt(st.nextToken()) - 1;
			assert x >= 1 && x <= n && y >= 1 && y <= n;

			for(int i = 0; i < n; i++) {
				for(int j = 0; j < m; j++) {
					int d = Math.abs(i - x) + Math.abs(j - y);
					if(a[i][j] > d)
						a[i][j] = d;
					if(k == 1 && a[i][j] > max)
						max = a[i][j];
				}
			}
		}

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(a[i][j] == max) {
					System.out.println((i + 1) + " " + (j + 1));
					return;
				}
			}
		}
    }

}

import java.io.*;

import java.util.*;



public class Solution implements Runnable {



	Scanner input;

	PrintWriter output;



	private void solve() throws Exception

	{

		int n = nextInt();

		int m = nextInt();

		int k = nextInt();

		int[] r = new int[k];

		int[] c = new int[k];

		for (int i = 0; i < k; i++)

		{

			r[i] = nextInt();

			c[i] = nextInt();

		}

		int best = -1;

		int bestr = -1;

		int bestc = -1;

		for (int i = 1; i <= n; i++)

		{

			for (int j = 1; j <= m; j++)

			{

				int d = n + m;

				for (int q = 0; q < k; q++)

				{

					d = Math.min(d, Math.abs(i - r[q]) + Math.abs(j - c[q]));

				}

				if (d < best) continue;

				best = d;

				bestr = i;

				bestc = j;

			}

		}

		out(bestr + " " + bestc);

	}



	private int nextInt() throws Exception

	{

		return input.nextInt();

	}



	private void out(String s)

	{

		output.println(s);

	}



	public void run() {

		try {

			solve();

		} catch (Exception ex) {

			throw new RuntimeException(ex);

		} finally {

			output.close();

		}

	}



	public Solution() throws IOException {

		input = new Scanner(new FileReader("input.txt"));

		output = new PrintWriter("output.txt");

	}



	public static void main(String[] args) throws IOException {

		Locale.setDefault(Locale.US);

		new Thread(new Solution()).start();

	}

}

