		b = new Pair[K];

		for (int i = 0; i < K; i++)

			b[i] = new Pair(sc.nextInt() - 1, sc.nextInt() - 1);



		Pair last = bfs();

		out.println((last.x) + " " + (last.y));

		out.flush();

		out.close();

	}



