        Segment L = htj[pre];
        Segment R = new Segment();
        htj[now] = R;
        curr++;
        R.num = L.num+1;
        if (l== r) {
            return;
        }
        R.ln = L.ln;
        R.rn = L.rn;
        int m = (r+l)>>1;
        if (e<=m) {
            R.ln = curr;
            insert(l,m,L.ln, R.ln, e);
        } else {
            R.rn = curr;
            insert(m+1,r,L.rn, R.rn, e);
        }
    }

    int query(int l,int r,int pre,int now,int k) {
        Segment L = htj[pre];
        Segment R = htj[now];
        if (R.num - L.num <= k) {
            return -1;
        }
        if (l == r) {
            return l;
        }
        int m = (l+r)>>1;
        int x = query(l,m,L.ln, R.ln, k);
        if (x != -1)
            return x;
        return query(m+1,r,L.rn, R.rn,k);
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = null;
        }

