    }

    static class TaskD {
        int[][] popular;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int q = in.readInt();
            int[] a = IOUtils.readIntArray(in, n);
            MiscUtils.decreaseByOne(a);
            popular = new int[4 * n][];
            init(0, 0, n - 1, a);
            IntList[] lists = new IntList[n];
            for (int i = 0; i < n; i++) {
                if (lists[a[i]] == null) {
                    lists[a[i]] = new IntArrayList();
                }
                lists[a[i]].add(i);
            }
            for (int i = 0; i < q; i++) {
                int l = in.readInt() - 1;
                int r = in.readInt() - 1;
                int k = in.readInt();
                IntList current = new IntArrayList();
                query(0, 0, n - 1, l, r, current);
                current.sort();
                boolean found = false;
                int threshold = (r - l + 1) / k + 1;
                for (int j = 0; j < current.size(); j++) {
                    int val = current.get(j);
                    if (j != 0 && val == current.get(j - 1)) {
                        continue;
                    }
                    if (lists[val].size() < threshold) {
                        continue;
                    }
                    if (count(lists[val], r) - count(lists[val], l - 1) >= threshold) {
                        out.printLine(val + 1);
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    out.printLine(-1);
                }
            }
        }

        private void query(int root, int left, int right, int from, int to, IntList current) {
            if (left > to || right < from) {
                return;
            }
            if (left >= from && right <= to) {
                for (int i : popular[root]) {
                    current.add(i);
                }
                return;
            }
            int middle = (left + right) >> 1;
            query(2 * root + 1, left, middle, from, to, current);
            query(2 * root + 2, middle + 1, right, from, to, current);
        }

        private int count(IntList list, int val) {
            int left = -1;
            int right = list.size() - 1;
            while (left < right) {
                int middle = (left + right + 1) >> 1;
                if (list.get(middle) <= val) {
                    left = middle;
                } else {
                    right = middle - 1;
                }
            }
            return left + 1;
        }

        private void init(int root, int left, int right, int[] a) {
            int[] current = Arrays.copyOfRange(a, left, right + 1);
            ArrayUtils.sort(current);
            int atLeast = (right - left + 1) / 5 + 1;
            IntList here = new IntArrayList();
            for (int i = 0; i + atLeast <= current.length; i++) {
                if (i != 0 && current[i] == current[i - 1]) {
                    continue;
                }
                if (current[i] == current[i + atLeast - 1]) {
                    here.add(current[i]);
                }
            }
            popular[root] = here.toArray();
            if (left != right) {
                int middle = (left + right) >> 1;
                init(2 * root + 1, left, middle, a);
                init(2 * root + 2, middle + 1, right, a);
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static interface IntIterator {
        public int value() throws NoSuchElementException;

        public boolean advance();

        public boolean isValid();

    }

    static class IOUtils {
        public static int[] readIntArray(InputReader in, int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = in.readInt();
            }
            return array;
        }

    }

    static interface IntComparator {
        public static final IntComparator DEFAULT = (first, second) -> {
            if (first < second) {
                return -1;
            }
            if (first > second) {
                return 1;
            }
            return 0;
        };

        public int compare(int first, int second);

    }

    static class IntArray extends IntAbstractStream implements IntList {
        private int[] data;

        public IntArray(int[] arr) {
            data = arr;
        }

        public int size() {
            return data.length;
        }

        public int get(int at) {
            return data[at];
        }

        public void addAt(int index, int value) {
            throw new UnsupportedOperationException();
        }

        public void removeAt(int index) {
            throw new UnsupportedOperationException();
        }

        public void set(int index, int value) {
            data[index] = value;
        }

    }

    static interface IntReversableCollection extends IntCollection {
    }

    static class ArrayUtils {
        public static int[] sort(int[] array) {
            return sort(array, IntComparator.DEFAULT);
        }

        public static int[] sort(int[] array, IntComparator comparator) {
            return sort(array, 0, array.length, comparator);
        }

        public static int[] sort(int[] array, int from, int to, IntComparator comparator) {
            if (from == 0 && to == array.length) {
                new IntArray(array).sort(comparator);
            } else {
                new IntArray(array).subList(from, to).sort(comparator);
            }
            return array;
        }

    }

    static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
        public IntIterator intIterator();

        default public Iterator<Integer> iterator() {
            return new Iterator<Integer>() {
                private IntIterator it = intIterator();

                public boolean hasNext() {
                    return it.isValid();
                }

                public Integer next() {
                    int result = it.value();
                    it.advance();
                    return result;
                }
            };
        }

        default public int compareTo(IntStream c) {
            IntIterator it = intIterator();
            IntIterator jt = c.intIterator();
            while (it.isValid() && jt.isValid()) {
                int i = it.value();
                int j = jt.value();
                if (i < j) {
                    return -1;
                } else if (i > j) {
                    return 1;
                }
                it.advance();
                jt.advance();
            }
            if (it.isValid()) {
                return 1;
            }
            if (jt.isValid()) {
                return -1;
            }
            return 0;
        }

    }

