			}



			for (int i = 0; i < ptr; i += 2) {

				all[i + 1] -= leastCnt;

			}



			for (int i = idx + 2; i < ptr; i++) {

				all[i - 2] = all[i];

			}



			ptr -= 2;

		}



		all = Arrays.copyOf(all, ptr);



