public class D_faster {



	static final int K = 4;



	static class Node {

		int l, r;

		Node left, right;



		int[] info;



		public Node(int l, int r, int[] a) {

			this.l = l;

			this.r = r;

			if (r - l == 1) {

				info = new int[] { a[l], 1 };

			} else {

				int m = (l + r) >> 1;

				left = new Node(l, m, a);

				right = new Node(m, r, a);

				info = merge(left.info, right.info);

			}

		}



		int[] getInfo(int ql, int qr) {

			if (ql >= r || l >= qr) {

				return null;

			}



			if (ql <= l && r <= qr) {

				return info;

			}



			int[] infoL = left.getInfo(ql, qr);

			int[] infoR = right.getInfo(ql, qr);

			return merge(infoL, infoR);

		}



	}



	static int[] merge(int[] a, int[] b) {



		if (a == null) {

			return b;

		}



		if (b == null) {

			return a;

		}



		int[] all = Arrays.copyOf(a, a.length + b.length);



		int ptr = a.length;



		outer: for (int i = 0; i < b.length; i += 2) {



			int val = b[i];

			int cnt = b[i + 1];



			for (int j = 0; j < ptr; j += 2) {

				if (val == all[j]) {

					all[j + 1] += cnt;

					continue outer;

				}

			}



			all[ptr++] = val;

			all[ptr++] = cnt;

		}



		while (ptr > 2 * K) {

			int idx = -1;

			int leastCnt = Integer.MAX_VALUE;

			for (int i = 0; i < ptr; i += 2) {

				if (all[i + 1] < leastCnt) {

					idx = i;

					leastCnt = all[i + 1];

				}

			}



			all[idx] = all[ptr - 2];

			all[idx + 1] = all[ptr - 1];



			ptr -= 2;



			for (int i = 0; i < ptr; i += 2) {

				all[i + 1] -= leastCnt;

			}



		}



		all = Arrays.copyOf(all, ptr);



