	public static int go(Node X, Node Y, int B)

	{

		Node XL = X.left, YL = Y.left;

		if(XL != null && B <= YL.des - XL.des){

			int res = go(XL, YL, B);

			if(res != -1)return res;

		}

		if(B <= Y.count - X.count){

			return X.num;

		}



		Node XR = X.right, YR = Y.right;

		if(XR != null && B <= YR.des - XR.des){

			int res = go(XR, YR, B);

			if(res != -1)return res;

		}

		return -1;

	}



	public static class Node

	{

		public int num;

		public int count;

		public int des;

		public Node left, right;



		public Node(int num, int count) {

			this.num = num;

			this.count = count;

			des = count;

		}



		public Node clone()

		{

			Node ret = new Node(num, count);

			ret.left = this.left;

			ret.right = this.right;

			return ret;

		}



		public void update()

		{

			des = count;

			if(left != null)des += left.des;

			if(right != null)des += right.des;

		}



		public Node insert(int x)

		{

			if(x < num){

				left = left.clone();

				left.insert(x);

			}else if(x > num){

				right = right.clone();

				right.insert(x);

			}else{

				count++; // e is always cloned.

			}

			update();

			return this;

		}



		public Node erase(int x)

		{

			if(x < num){

				left = left.clone();

				left.erase(x);

			}else if(x > num){

				right = right.clone();

				right.erase(x);

			}else{

				count--; // e is always cloned.

			}

			update();

			return this;

		}



		public String toString(String indent) {

			StringBuilder builder = new StringBuilder();

			if(left != null){

				builder.append(left.toString(indent + "  "));

			}

			builder.append("[num=");

			builder.append(num);

			builder.append(", count=");

			builder.append(count);

			builder.append(", des=");

			builder.append(des);

			builder.append("]\n");

			if(right != null){

				builder.append(right.toString(indent + "  "));

			}

			return builder.toString();

		}

	}



