	public static int[][] enumFIF(int n, int mod) {
		int[] f = new int[n + 1];
		int[] invf = new int[n + 1];
		f[0] = 1;
		for (int i = 1; i <= n; i++) {
			f[i] = (int) ((long) f[i - 1] * i % mod);
		}
		long a = f[n];
		long b = mod;
		long p = 1, q = 0;
		while (b > 0) {
			long c = a / b;
			long d;
			d = a;
			a = b;
			b = d % b;
			d = p;
			p = q;
			q = d - c * q;
		}
		invf[n] = (int) (p < 0 ? p + mod : p);
		for (int i = n - 1; i >= 0; i--) {
			invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
		}
		return new int[][]{f, invf};
	}

	public static long[] enumPows(int a, int n, int mod)
	{
		a %= mod;
		long[] pows = new long[n+1];
		pows[0] = 1;
		for(int i = 1;i <= n;i++)pows[i] = pows[i-1] * a % mod;
		return pows;
	}


	void solve()
	{
		int N = ni();
		final int mod = ni();

		long[] p2 = enumPows(2, 1000, mod);
		int[][] fif = enumFIF(1000, mod);

		long[][] dp = new long[N+2][N+1];
		dp[0][0] = 1;
		for(int i = 0;i <= N+1;i++){
			for(int j = 0;j <= N;j++){
				// 11110
				for(int k = 1;i+k+1 <= N+1 && j+k <= N;k++){
					dp[i+k+1][j+k] += dp[i][j] * fif[1][k] % mod * p2[k-1];
					dp[i+k+1][j+k] %= mod;
				}
			}
//			tr(dp[i]);
		}

		long ans = 0;
		for(int i = 1;i <= N;i++){
			ans += dp[N+1][i] * fif[0][i];
			ans %= mod;
		}
		out.println(ans);
	}

