    static PrintWriter pw;
    static _Scanner sc;

    public static void main(String[] args) throws Exception {
        sc = new _Scanner(System.in);
        pw = new PrintWriter(System.out);
        //long startTime = System.currentTimeMillis();
        //int t = sc.nextInt();
        int t = 1;
        while (t-- > 0) {
            solve();
        }
        pw.flush();
