            for(int j=0; j<m-1; j++) {
                a[i][j] = sc.nextInt();
            }
        }
        for(int i=0 ;i<n-1; i++) {
            for(int j=0; j<m; j++) {
                b[i][j] = sc.nextInt();
            }
        }

        if(k % 2 == 1) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (j > 0)
                        out.print(" ");
                    out.print("-1");
                }
                out.println();
            }
            return;
        }


        int[][] prev = new int[n][m];
        k /= 2;
        for(int l=0; l<k; l++) {
            int[][] next = new int[n][m];
            for(int i=0; i<n; i++) {
                for(int j=0; j<m; j++) {
                    next[i][j] = Integer.MAX_VALUE;
                    if(i>0) {
                        next[i][j] = Math.min(next[i][j], prev[i-1][j] + b[i-1][j]);
