                        next[i][j] = Math.min(next[i][j], prev[i+1][j] + b[i][j]);
                    }
                    if(j>0) {
                        next[i][j] = Math.min(next[i][j], prev[i][j-1] + a[i][j-1]);
                    }
                    if(j+1<m) {
                        next[i][j] = Math.min(next[i][j], prev[i][j+1] + a[i][j]);
                    }
                }
            }
            prev = next;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (j > 0)
                    out.print(" ");
                out.print(prev[i][j] * 2);
            }
            out.println();
        }


    }



