                    dis[i][j + 1][1] = tmp;
                }
            }
            for (int i = 0; i < n - 1; i++) {
                for (int j = 0; j < m; j++) {
                    tmp = in.nextInt();
                    dis[i][j][2] = tmp;
                    dis[i + 1][j][3] = tmp;
                }
            }
            int[][] ans = new int[n][m];

            if (k % 2 == 1) {
                Algo.fill(ans, -1);
            } else {
                int halfK = k / 2;
                int[][][] dp = new int[halfK + 1][n][m];
                Algo.fill(dp, M);

                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        dp[0][i][j] = 0;
                    }
                }

                for (int step = 1; step <= halfK; step++) {
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < m; j++) {
                            for (int d = 0; d < dir.length; d++) {
                                int toX = i + dir[d][0];
                                int toY = j + dir[d][1];
                                if (toX < 0 || toY < 0 || toX >= n || toY >= m) continue;
                                dp[step][i][j] = Math.min(dp[step - 1][toX][toY] + 2 * dis[i][j][d], dp[step][i][j]);
                            }
                        }
                    }
                }
                ans = dp[halfK];
            }


            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(ans[i][j]);
                    out.print(' ');
                }
                out.println("");
            }


        }

    }

