public class D {
  void solve() {
    int n = nextInt();
    int m = nextInt();
    int k = nextInt();
    int[][][] cost = new int[n][m][4];
    for (int i = 0; i<n; i++) {
      for (int j = 0; j<m; j++) {
        for (int j2 = 0; j2<4; j2++) {
          cost[i][j][j2]=Integer.MAX_VALUE/4;
        }
      }
    }
    for (int i = 0; i<n; i++) {
      for (int j = 0; j<m-1; j++) {
        int c = nextInt();
        cost[i][j][0]=c;
        cost[i][j+1][1]=c;
      }
    }
    for (int i = 0; i<n-1; i++) {
      for (int j = 0; j<m; j++) {
        int c = nextInt();
        cost[i][j][2]=c;
        cost[i+1][j][3]=c;
      }
    }
    int[][][] path = new int[k>=4 ? k/2+1 : 2][n][m];
    for (int i = 0; i<n; i++) {
      for (int j = 0; j<m; j++) {
        int minval = cost[i][j][0];
        minval=min(minval, cost[i][j][1]);
        minval=min(minval, cost[i][j][2]);
        minval=min(minval, cost[i][j][3]);
        path[1][i][j]=minval;
      }
    }
    for (int k2 = 2; k2<=k/2; k2++) {
      for (int i = 0; i<n; i++) {
        for (int j = 0; j<m; j++) {
          int minval = Integer.MAX_VALUE/4;
          if (i>0)
            minval=min(minval, path[k2-1][i-1][j]+cost[i][j][3]);
          if (i<n-1)
            minval=min(minval, path[k2-1][i+1][j]+cost[i][j][2]);
          if (j>0)
            minval=min(minval, path[k2-1][i][j-1]+cost[i][j][1]);
          if (j<m-1)
            minval=min(minval, path[k2-1][i][j+1]+cost[i][j][0]);
          path[k2][i][j]=minval;
        }
      }
    }
    for (int i = 0; i<n; i++) {
      for (int j = 0; j<m; j++) {
        path[0][i][j]=-1;
      }
    }
    int k_show = k%2==1 ? 0 : k/2;
    if (k_show>0) {
      for (int i = 0; i<n; i++) {
        for (int j = 0; j<m; j++) {
          path[k_show][i][j]*=2;
        }
      }
    }
    for (int i = 0; i<n; i++) {
      for (int j = 0; j<m; j++) {
        out.printf("%d ", path[k_show][i][j]);
      }
      out.println();
    }
  }
  static int nextInt() {
    return Integer.parseInt(nextToken());
  }
  static String nextToken() {
    while (!st.hasMoreTokens()) {
      try {
        st=new StringTokenizer(br.readLine());
      } catch (Exception e) {
        throw new RuntimeException("out of tokens!");
      }
    }
    return st.nextToken();
  }
  static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
  static StringTokenizer st = new StringTokenizer("");
  static PrintWriter out = new PrintWriter(System.out);
  public static void main(String[] a) {
    new D().solve();
    out.flush();
  }
}

