public class D {

	public static BufferedReader br;
	public static PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
	static class Edge{
		int r, c;
		long w;
		public Edge(int a, int d, long b) {
			r=a;
			c=d;
			w=b;
		}
	}

	public static void main(String[] args) throws IOException {
		readInput();
		out.close();
	}

	static class State implements Comparable<State>{
		public int r, c, t;
		public long w;
		public State(int a, int b, int f, long d) {
			r=a;
			c=b;
			t=f;
			w=d;
		}
		public int compareTo(State o) {
			if (w < o.w) return -1;
			else if (w > o.w) return 1;
			return 0;
		}
	}
	// Default state is 15.
	static long solve(int i, int j, int t) {
		//System.out.println(i + " " + j + " " + t  +" " + k/2);
		if (t == k/2) return (dp[i][j][t] = 0);
		if (dp[i][j][t] > 1e15) {
			for (Edge e: adj[i][j]) {
				dp[i][j][t] = Long.min(dp[i][j][t], solve(e.r,e.c,t+1)+e.w);
			}
		}
		return dp[i][j][t];
	}

	static int n, m, k;
	static long[][][] dp;
	static List<Edge>[][] adj;
	public static void readInput() throws IOException {
		br = new BufferedReader(new InputStreamReader(System.in));
		// br = new BufferedReader(new FileReader("in.in"));
		StringTokenizer st= new StringTokenizer(br.readLine());
		n = Integer.parseInt(st.nextToken());
		m = Integer.parseInt(st.nextToken());
		k = Integer.parseInt(st.nextToken());
		if (k % 2 == 1) {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					out.print(-1 + " ");
				}
				out.println();
			}
			return;
		}
		dp = new long[n][m][k/2+1];
		for (long[][] a: dp) for (long[] b: a) Arrays.fill(b, Long.MAX_VALUE/5);
		adj = new List[n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) adj[i][j] = new ArrayList<Edge>();
		}
		for (int i = 0; i < n; i++) {
			st = new StringTokenizer(br.readLine());
			for (int j = 0; j < m-1; j++) {
				long x = Integer.parseInt(st.nextToken());
				adj[i][j].add(new Edge(i, j+1, x));
				adj[i][j+1].add(new Edge(i,j,x));
			}
		}
		for (int i = 0; i < n-1; i++) {
			st = new StringTokenizer(br.readLine());
			for (int j = 0; j < m; j++) {
				long x = Integer.parseInt(st.nextToken());
				adj[i+1][j].add(new Edge(i, j, x));
				adj[i][j].add(new Edge(i+1,j,x));
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				long ans = solve(i,j,0)*2;
				out.print(ans + " ");
			}
			out.println();
		}
	}
}

