        if(dp[x][y][moves]!=-1) return dp[x][y][moves];
        int ans=Integer.MAX_VALUE;
        if(x-1>=0){
            ans=Math.min(ans,solve(x-1,y,moves-1,dp,xf,xb,yf,yb,r,c)+yb[x][y]);
        }
        if (x + 1 < r) {
