        }
        if(y-1>=0){
            ans=Math.min(ans,solve(x,y-1,moves-1,dp,xf,xb,yf,yb,r,c)+xb[x][y]);
        }
        if (y + 1 < c) {
            ans=Math.min(ans,solve(x,y+1,moves-1,dp,xf,xb,yf,yb,r,c)+xf[x][y]);
        }
        dp[x][y][moves]=ans;
        return ans;
