	void solve(int T) {
		int n = ni();
		int m = ni();
		int k = ni();
		int h[][] = na(n, m - 1);
		int v[][] = na(n - 1, m);
		if (k % 2 == 1) {
			for (int r = 0; r < n; r++) {
				for (int c = 0; c < m; c++)
					out.print("-1 ");
