		}
		k /= 2;
		int d[][] = new int[n][m];
		while (k-- > 0) {
			int cur[][] = new int[n][m];
			for (int r = 0; r < n; r++)
				for (int c = 0; c < m; c++) {
					cur[r][c] = Integer.MAX_VALUE;
					// hor <--
					if (c > 0) {
						cur[r][c] = d[r][c - 1] + h[r][c - 1];
					}
					if (c < m - 1) {
						cur[r][c] = Math.min(cur[r][c], d[r][c + 1] + h[r][c]);
					}
					//
					if (r > 0) {
						cur[r][c] = Math.min(cur[r][c], d[r - 1][c] + v[r - 1][c]);
					}
					if (r < n - 1) {
						cur[r][c] = Math.min(cur[r][c], d[r + 1][c] + v[r][c]);
					}
				}
			d = cur;
		}
