        if(Integer.bitCount(mask) == 1 && (mask&(1<<i)) != 0) {
            dp[mask][i] = 1;
        } else if(Integer.bitCount(mask) > 1 && (mask&(1<<i)) != 0 && i != Integer.numberOfTrailingZeros(mask)) {
            dp[mask][i] = 0;
            for (int j = 0; j < n; j++) {
                if(graph[i][j]) dp[mask][i] = dp[mask][i] + f(mask^(1<<i), j, dp, graph, n);
            }
        } else {
            dp[mask][i] = 0;
        }

