                g[i][j] = true;*/
        long[] am = new long[n + 1];
        long[][] ways = new long[1 << (n - 1)][n];
        for (int start = 0; start < n; ++start) {
            for (int mask = 0; mask < (1 << (n - start - 1)); ++mask)
                for (int last = start; last < n; ++last) {
                    ways[mask][last - start] = 0;
                }
            ways[1 >> 1][0] = 1;
            for (int mask = 1; mask < (1 << (n - start)); mask += 2) {
                int cnt = 0;
                int tmp = mask;
                while (tmp > 0) {
                    ++cnt;
                    tmp = tmp & (tmp - 1);
                }
                for (int last = start; last < n; ++last)
