                        long amm = ways[mask >> 1][last - start];
                        for (int i = start; i < n; ++i)
                            if ((mask & (1 << (i - start))) == 0 && g[last][i]) {
                                ways[(mask | (1 << (i - start))) >> 1][i - start] += amm;
                            }
                        if (g[last][start])
                            am[cnt] += ways[mask >> 1][last - start];
