//        for (int i = 1; i
//                <= N; i++) {
//            for (int j = i + 1; j <= N; j++) {
//                System.out.println(i + " " + j);
//            }
//        }
        int n = in.nextInt();
        int m = in.nextInt();
        dp = new long[n][1 << n + 1] ;

        map = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            map[a][b] = true;
            map[b][a] = true;

        }
        for(long []temp : dp){
            Arrays.fill(temp, -1);
        }
        long result = 0;
        for(int i = 0; i < n; i++){
            result += cal((1<<i),i,i,1);
        }
        out.println((result/2));

        out.close();
    }
    public static long cal(int mask, int from, int to, int len){
        if(dp[to][mask]!= -1){
            return dp[to][mask];
        }
        long result = 0;
        if(len > 2 && map[from][to]){
            result++;
        }
        for(int i = from+1; i< map.length; i++){
            if(map[to][i] && (mask & (1<<i)) == 0){
                result += cal(mask|(1<<i), from,i,len + 1);
            }
        }
        dp[to][mask] = result;
        return result;

    }


    public static class FT {

        int[] data;

        FT(int n) {
            data = new int[n];
        }

        public void update(int index, int value) {
            while (index < data.length) {
                data[index] += value;
                index += (index & (-index));
            }
        }

        public int get(int index) {
            int result = 0;
            while (index > 0) {
                result += data[index];
                index -= (index & (-index));
            }
            return result;

        }
    }

    public static long gcd(long a, long b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    public static long pow(long a, long b) {
        if (b == 0) {
            return 1;
        }
        if (b == 1) {
            return a;
        }
        long val = pow(a, b / 2);
        if (b % 2 == 0) {
            return val * val ;
        } else {
            return val * (val * a) ;
        }
    }

