public class D {
    static boolean[][] adj;
    static int n;
    static int first;

    public static void main(String[] args) throws IOException {
        InputReader in = new InputReader();
        n = in.nextInt();
//       n = 19;?
        int m = in.nextInt();
        adj = new boolean[n][n];
//       for (int i = 0; i < n; i++) {
//       for (int j = 0; j < n; j++) {
//       adj[i][j] = true;
//       }
//       }
        dp = new long[1 << n][n];
        for (int i = 0; i < m; i++) {
            int f = in.nextInt() - 1;
            int t = in.nextInt() - 1;
            adj[f][t] = adj[t][f] = true;
        }

        boolean[] v = new boolean[1 << n];
        long res = 0;
        for (int f = 0; f < n; f++) {
            first = f;
            int cnt;
            for (int i = 0; i < 1 << n; i+=(1<<first))
                if ((i & (1 << first)) == 0)
                    for (int j = 0; j < n; j++)
                        dp[i][j] = -1;

            for (int i = 0; i < 1 << n; i+= (1<<first)) {
                cnt = Integer.bitCount(i);
                if ((i & (1 << first)) == 0 && !v[i | (1 << first)] && cnt > 1) {
                    v[i | (1 << first)] = true;
                    res += solve(i, first, cnt);
                }
            }
        }
        System.out.println(res / 2);
    }

    static long[][] dp;

    public static long solve(int msk, int lst, int cnt) {
        if (cnt == 0)
            return (adj[lst][first]) ? 1 : 0;
        if (dp[msk][lst] != -1)
            return dp[msk][lst];
        long res = 0;
        for (int i = 0; i < n; i++)
            if (adj[lst][i] && (msk & (1 << i)) > 0)
                res += solve(msk ^ (1 << i), i, cnt - 1);
        return dp[msk][lst] = res;
    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer st;

        public InputReader() throws IOException {
            in = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer(in.readLine());
        }

        public String next() throws IOException {
            while (!st.hasMoreElements())
                st = new StringTokenizer(in.readLine());
            return st.nextToken();
        }

        public int nextInt() throws NumberFormatException, IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws NumberFormatException, IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		while ( sc.hasNextInt() ) {
			int n = sc.nextInt();
			long m = sc.nextInt();
			boolean edge[][] = new boolean[n][n];
			long dp[][] = new long[1<<n][n];
			for ( long i = 1 ; i<=m ; ++i ) {
	 			int u = sc.nextInt();   
				int v = sc.nextInt();
				-- u;
				-- v;
				edge[u][v] = edge[v][u] = true;
			}
			for ( int i = 0 ; i<n ; ++i ) {
				dp[1<<i][i] = 1;
			}
			long res = 0;
			for ( int i = 1 ; i<(1<<n) ; ++i ) {
				int first = cal(i);
				for ( int j = 0 ; j<n ; ++j ) {
					if ( dp[i][j]==0 ) {
						continue;
					}
					for ( int k = first ; k<n ; ++k ) {
 						if ( j==k || !edge[j][k] ) {
							continue;
						}
						if ( k==first && (i&(1<<k))!=0 ) {
							res += dp[i][j];
						}
						if ( (i&(1<<k))==0 ) {
							dp[i|(1<<k)][k] += dp[i][j];
						}
					}
				}
			}
			res -= m;
			System.out.println(res/2);		
		}
	}
	public static int cal( int x ) {
		int ord = 0;
		while ( true ) {
			if ( (x&(1<<ord))!=0 ) {
				break;
			}
			++ ord;
		}
		return ord;
	}
	public static boolean judge( int x ) {
		int cnt = 0;
		while ( x>=1 ) {
			if ( (x&1)==1 ) {
				++ cnt;
			}
			x >>= 1;
		}
		return cnt >= 3;
	}
}

