		BasicInputOutput()
		{
			delim = " \t\n\r\f";
			initialize();
		}
		BasicInputOutput( String s )
		{
			delim = s;
			initialize();
		}
		private void initialize()
		{
			bufferReader = new BufferedReader( new InputStreamReader( System.in ));
