		}

		public < T > void write( char sep, T... var )throws IOException
		{
			if ( var.length == 0 )
				return ;
			bufferWriter.write( var[0].toString());
			for ( int i = 1; i < var.length; i++ )
				bufferWriter.write( sep + var[i].toString());
		}

		public void flush()throws IOException
		{
			bufferWriter.flush();
		}
	}

