		PrintWriter out = new PrintWriter(System.out);

		int n = Integer.valueOf(s.readLine());
		double[][] prob = new double[n][n];
		double[] dp = new double[1<<n];
		for (int i = 0 ; i < n ; i++) {
			String[] line = s.readLine().split(" ");
			for (int j = 0 ; j < n ; j++) {
				prob[i][j] = Double.valueOf(line[j]);
			}
		}

