		for (int p = (1<<n)-1 ; p >= 1 ; p--) {
			if (dp[p] > 0.0d) {
				int left = Integer.bitCount(p);
				if (left == 1) {
					continue;
				}
				double baseProb = 1.0d / (left * (left - 1) / 2);
