								w[mask ^ (1 << j)] += w[mask] * p[i][j] / count;
								w[mask ^ (1 << i)] += w[mask] * (1 - p[i][j])
										/ count;
							}
		}
		for (int i = 0; i < n; i++) {
			if (i != 0)
				System.out.print(' ');
			System.out.printf("%.6f", w[1 << i]);
		}
		System.out.println();
	}
}

