public class E {

    public static double[] dp;
    public static double[][] data;
    public static int n;

    public static void main(String[] args) {
        Scanner in = new Scanner();
        PrintWriter out = new PrintWriter(System.out);
        n = in.nextInt();
        data = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                data[i][j] = in.nextDouble();
            }
        }
        dp = new double[1 << n];
        Arrays.fill(dp, -1);
        for (int i = 0; i < n; i++) {
            int a = 1 << i;
            out.print(cal(a) + " ");
        }
        out.close();
        //System.out.print(builder.toString());
    }

    public static double cal(int mask) {
        if (mask == (1 << n) - 1) {
            //  System.out.println(mask);
            return 1;
        }
        if (dp[mask] != -1) {
            return dp[mask];
        }
        double result = 0;
        int c = 0;       
        for (int i = 0; i < n; i++) {
            int a = 1 << i;
            if ((a & mask) != 0) {
                c++;
                for (int j = 0; j < n; j++) {
                    int b = 1 << j;
                    if ((b & mask) == 0) {
                        result += (data[i][j] * cal(mask | b));
                    }
                }
            }
        }

        int nC2 = (c + 1) * c / 2;
        dp[mask] = result / nC2;
        return dp[mask];
    }

