			cr.clear();
			cr.addAll(nx);
			nx.clear();
			for (Iterator<Integer> iterator = cr.iterator(); iterator.hasNext();) {
				int curr = iterator.next();
				for (int i = 0; i < n; i++) {
					fish[i] = ((1 << i) & curr) != 0;
				}
				int fishn = 0;
				for (int i = 0; i < n; i++) {
					if (fish[i]) fishn++;
				}
