			sen[i][1] = iread();
		}
		double maxposs=0;
		int[] rasp=new int[n];
		rasp[n-1]=k;
		maxposs=Math.max(maxposs, poss(A,sen,rasp));
		while(nextPerm(rasp,k)==0)
			maxposs=Math.max(maxposs, poss(A,sen,rasp));
		out.write(maxposs+"\n");
	}

