		n = nextInt();
		int k = nextInt();
		a = nextInt();
		b = new int[n];
		l = new int[n];
		sw = new int[n];
		for (int i = 0; i < n; i++) {
			b[i] = nextInt();
			l[i] = nextInt();
		}
		rek(0, k);
		out.printf("%.10f", ans);
	}

