            for (int i = 0; i < n; i++) 
                if (((mask >> i) & 1) == 1) {
                    prob *= loyal[i] / 100.0;
                    vote++;
                }
                else {
                    prob *= 1 - loyal[i] / 100.0;
                    kill += level[i];
                }
            if (vote >= needVotes)
                res += prob;
            else
                res += prob * plLev / (kill + plLev);
        }

