        }
        for(int i = 0; i < dp.length; i++) {
            int j = time[i];
                for(int k = 0; k < 3; k++) {
                    if(dp[i][k] == 0) continue;
                    for(int bi = 0; bi < n; bi++)
                        if(tarr[bi] + j <= t && (i & 1 << bi) == 0 && garr[bi] != k) {
                                    dp[i | 1 << bi][garr[bi]] = 
                                        (dp[i | 1 << bi][garr[bi]] + dp[i][k]) % MOD;
                        }
                }
        }
        long ans = 0;
        for(int i = 0; i < dp.length; i++)
            for(int j = 0; j < 3; j++)
            if(time[i] == t) ans = (ans + dp[i][j]) % MOD;
        out.println(ans);
        out.flush();
	}
    static class FastScanner {
