public class G extends PrintWriter {

    void run() {
        long mod = 1_000_000_000 + 7;
        int n = nextInt();
        int m = nextInt();

        int[] t = new int[n];
        int[] g = new int[n];

        for (int i = 0; i < n; i++) {
            t[i] = nextInt();
            g[i] = nextInt() - 1;
        }

        int k = 1 << n;

        long[][] dp = new long[k][n];

        for (int i = 0; i < n; i++) {
            dp[1 << i][i] = 1;
        }

        for (int mask = 0; mask < k; mask++) {
            if (Integer.bitCount(mask) <= 1) {
                continue;
            }

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    for (int j = 0; j < n; j++) {
                        if ((mask & (1 << j)) == 0 || g[i] == g[j]) {
                            continue;
                        }
                        dp[mask][i] = (dp[mask][i] + dp[mask ^ (1 << i)][j]) % mod;
                    }
                }
            }
        }

        long ans = 0;
        for (int mask = 0; mask < k; mask++) {
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += t[i];
                }
            }
            if (sum == m) {

                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        ans = (ans + dp[mask][i]) % mod;
                    }
                }

            }

        }

        println(ans);

    }

