    static void rec(int id) {
        if (id == used.size()) {
            check();
            return;
        }

        for(int i = 0;i < n;i++) {
            num[id] = i;
            rec(id + 1);
        }
    }

    static void check() {
        int new_ans = 0;
        for(int i = 0;i < n;i++) {
            int max = 0;
            for(int j = 0;j < used.size();j++) {
                max = Math.max(max, a[(i + num[j]) % n][used.get(j)]);
            }
            new_ans += max;
        }
        ans = Math.max(ans, new_ans);
    }

