			for (int[] x : memo)
				Arrays.fill(x, -1);
			a = new int[n][m];
			for (int i = 0; i < n; i++)
				for (int j = 0; j < m; j++)
					a[i][j] = sc.nextInt();
			out.println(dp(0, 0));
		}
		out.close();

	}

