	void solve()
	{
		for(int T = ni();T > 0;T--){
			int n = ni(), m = ni();
			int[][] a = new int[n][];
			for(int i = 0;i < n;i++)a[i] = na(m);

			int[][] sss = new int[1<<n][m];
			for(int i = 1;i < 1<<n;i+=2){
				int[] ss = new int[m];
				for(int j = 0;j < m;j++){
					int cur = i;
					int lmax = 0;
					for(int sh = 0;sh < n;sh++){
						int s = 0;
						for(int k = 0;k < n;k++){
							if(cur<<~k<0){
								s += a[k][j];
							}
						}
						lmax = Math.max(lmax, s);
						cur = cur>>>1|(cur&1)<<n-1;
					}
					ss[j] = lmax;
				}
				sss[i] = ss;
			}
			ptns = new HashMap<>();
			dfs(new int[n], 0, -1);
			int ans = 0;
			if(n == 4 && m >= 4){
				int[] one = Arrays.copyOf(sss[1], m);
				Arrays.sort(one);
				ans = one[m-1] + one[m-2] + one[m-3] + one[m-4];
			}

			for(int[] cs : ptns.values()){
				if(cs.length == 4)continue;
				int[] u = new int[cs.length];
				inner:
				do{
					for(int i = 0;i < cs.length;i++){
						for(int j = i+1;j < cs.length;j++){
							if(u[i] == u[j])continue inner;
						}
					}
					int val = 0;
					for(int i = 0;i < cs.length;i++){
						val += sss[cs[i]][u[i]];
					}
					ans = Math.max(ans, val);
				}while(inc(u, m));
			}
			out.println(ans);
		}
	}

	public static boolean inc(int[] a, int base) {
		int n = a.length;
		int i;
		for (i = n - 1; i >= 0 && a[i] == base - 1; i--)
			;
		if (i == -1)
			return false;

		a[i]++;
		Arrays.fill(a, i + 1, n, 0);
		return true;
	}


	Map<Long, int[]> ptns = new HashMap<>();
//	Set<Long> all = new HashSet<>();

	void dfs(int[] a, int pos, int max)
	{
		if(pos == a.length){
			int[] ptn = new int[max+1];
			int n = a.length;
			for(int i = 0;i < n;i++){
				ptn[a[i]] |= 1<<i;
			}
			for(int i = 0;i <= max;i++){
				ptn[i] = ptn[i]>>>Integer.numberOfTrailingZeros(ptn[i]);
			}
//			for(int i = 0;i <= max;i++){
