										ndp[k|cur], dp[k] + ls[j]);
							}
						}
					}
				}
				dp = ndp;
			}
			out.println(dp[(1<<n)-1]);
		}
	}

	int rot(int x, int n)
	{
		int ret = x;
		for(int i = 0;i < n;i++){
			x = x>>>1|(x&1)<<n-1;
				ret = Math.min(ret, x);
