            for (int i = 0; i < m; i++) {
                cols[i].max = 0;
                cols[i].n = n;
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    cols[j].data[i] = io.readInt();
                    cols[j].max = Math.max(cols[j].max, cols[j].data[i]);
