				to[w[i]-'a'][w[i+1]-'a']++;
				to[w[i+1]-'a'][w[i]-'a']++;
			}

		cost = new int[1 << m];	
		for (int i = 0; i < (1 << m); i++)
			for (int j = 0; j < m; j++)
