							v+=cnt[j][k];
						}
					}
				}
			}
			for(int j=0;j<m;j++) {
				if((i&(1<<j))>0) {
					dp[i]=Math.min(dp[i], dp[i-(1<<j)]+v);
				}
			}
		}

		return dp[(1<<m)-1];
	}
}



